  y += boxH + 6;
  if (y + 74 > H - 22) y = neueSeite("SERVICE- & BERATUNGSAUFTRAG");
  strich(TEXT); doc.setLineWidth(0.3); doc.rect(RA, y - 3, 3.4, 3.4, "S");
