/* Paragrafen in PDF-Zeilen umsetzen; `ersetze` füllt die Platzhalter */
function vertragsZeilen(titel, parteiZeilen, paragrafen, ersetze) {
  const leer = "______________________";
  const f = FIRMENDATEN;
  const z = [];
  z.push("Auftraggeber: EGC Energie, vertreten durch " + (f.vertreter || leer) + ", "
    + (f.strasse || leer) + ", " + (f.ort || leer) + (f.ustId ? ", USt-IdNr. " + f.ustId : "")
    + ", nachfolgend \"EGC\"");
  z.push("und");
  parteiZeilen.forEach((x) => z.push(x));
  z.push("schließen folgenden " + titel + ".");
  paragrafen.forEach((s) => {
    z.push(" ");
    z.push({ text: s.h, gross: true });
    if (s.p) z.push(ersetze(s.p));
    if (s.n) s.n.forEach((t, i) => z.push((i + 1) + ". " + ersetze(t)));
    if (s.extra) { z.push(" "); z.push(ersetze(s.extra)); }
  });
  return z;
}

/* ---------- Handelsvertretervertrag ----------
   Liegt beim Mitarbeiter unter `vertrag` und damit in den geschützten Stammdaten.
   Anschrift, Steuernummer und IBAN kommen aus den Stammdaten des Partners. */
async function vertragPdf(m, mitarbeiter) {
  const v = m.vertrag || {};
  const sd = m.stammdaten || {};
  const leer = "______________________";
  const bild = async (d) => {
    if (!d) return null;
    try { return { bild: await dateiInhalt(d), breite: d.breite, hoehe: d.hoehe }; }
    catch (e) { return null; }
  };
  const gf = await bild(v.gfUnterschrift);
  const vp = await bild(v.partnerUnterschrift);
  const satz = num(parseFloat(v.satz) || 0, 0) + " %";
  const steuer = sd.ustId || sd.steuernummer;
  const z = vertragsZeilen("Handelsvertretervertrag", [
    "Handelsvertreter: " + (sd.firma ? sd.firma + " (" + m.name + ")" : m.name) + ", "
      + (sd.strasse || leer) + ", " + ([sd.plz, sd.ort].filter(Boolean).join(" ") || leer)
      + (steuer ? ", St.-Nr./USt-IdNr.: " + steuer : "") + ", nachfolgend \"Handelsvertreter\"",
  ], HV_PARAGRAFEN, (t) => t.replace("{P}", satz)
    .replace("{IBAN}", sd.iban || "________________________________"));
  z.push(" ");
  z.push({ text: "Unterschriften", gross: true });
  z.push("Für EGC Energie, " + (v.gfName || FIRMENDATEN.vertreter || leer) + ":");
  if (gf && gf.bild) z.push(gf); else z.push(" ");
  z.push("Ort, Datum: " + (FIRMENDATEN.ort ? FIRMENDATEN.ort.replace(/^\d+\s*/, "") + ", " : "")
    + (v.gfDatum ? datum(v.gfDatum) : leer));
  z.push(" ");
  z.push("Handelsvertreter, " + m.name + ":");
  if (vp && vp.bild) z.push(vp); else z.push(" ");
  z.push("Ort, Datum: " + (v.partnerDatum ? (sd.ort ? sd.ort + ", " : "") + datum(v.partnerDatum) : leer));
  const pdf = erzeugePdf("Handelsvertretervertrag_" + m.name.replace(/\W+/g, "_") + ".pdf",
    "Handelsvertretervertrag", z);
  if (pdf) dateiLaden(pdf);
}

/* ---------- Strukturanfragen ----------
   Der Teamleiter schlägt einen neuen Vertriebspartner für seine Struktur vor.
   Die Geschäftsführung gibt frei, unterschreibt und erzeugt die Einladung. */
const ANFRAGE_STATUS = {
  offen: { label: "Wartet auf Geschäftsführung", farbe: C.gas },
  freigegeben: { label: "Freigegeben", farbe: C.ok },
  abgelehnt: { label: "Abgelehnt", farbe: C.warn },
  zurueckgezogen: { label: "Zurückgezogen", farbe: C.muted },
};

const StrukturStatus = ({ status }) => {
  const st = ANFRAGE_STATUS[status] || ANFRAGE_STATUS.offen;
  return (
    <span className="inline-flex items-center gap-1.5 text-xs" style={{ color: st.farbe }}>
      <span className="w-2 h-2 rounded-full" style={{ background: st.farbe }} />{st.label}
    </span>
  );
};

function LinkKopieren({ url }) {
  const [kopiert, setKopiert] = useState(false);
  return (
    <div>
      <div className="p-3 rounded text-sm break-all"
           style={{ background: "#F6F8FA", border: "1px solid " + C.line }}>{url}</div>
      <div className="mt-2">
        <Btn icon={Check} onClick={() => {
          try { navigator.clipboard.writeText(url); setKopiert(true); } catch (e) { /* manuell kopieren */ }
        }}>{kopiert ? "Kopiert" : "Link kopieren"}</Btn>
      </div>
    </div>
  );
}

function Strukturanfragen({ anfragen, setAnfragen, user }) {
  const leer = () => ({ name: "", email: "", telefon: "", satz: "", notiz: "" });
  const [neu, setNeu] = useState(null);
  const [auswahl, setAuswahl] = useState(null);
  const meine = anfragen.filter((x) => x.vonId === user.id);
  const gewaehlt = meine.find((x) => x.id === auswahl);
  const eigenerSatz = eigenerSatzVon(user);
  const satz = parseFloat(String((neu || {}).satz || "").replace(",", "."));
  const satzOk = !isNaN(satz) && satz > 0 && satz <= eigenerSatz;
  const mailOk = neu && /^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(neu.email.trim());

  const senden = () => {
    setAnfragen([{
      id: "SA-" + uid(), vonId: user.id, von: user.name, team: user.team || "-",
      datum: heute(), status: "offen",
      name: neu.name.trim(), email: neu.email.trim(), telefon: neu.telefon.trim(),
      rolle: "Vertriebspartner", satz, upline: user.id, notiz: neu.notiz.trim(),
    }, ...anfragen]);
    setNeu(null);
  };

  if (neu)
    return (
      <div className="rounded p-5" style={{ background: C.card, border: "1px solid " + C.line }}>
        <div className="flex items-center gap-3 mb-5">
          <button onClick={() => setNeu(null)} style={{ color: C.muted }}><ArrowLeft size={18} /></button>
          <h2 className="text-lg">Neuen Vertriebspartner anfragen</h2>
        </div>
        <div className="grid sm:grid-cols-2 gap-4">
          <Feld label="Name" value={neu.name} onChange={(v) => setNeu({ ...neu, name: v })} />
          <Feld label="E-Mail" value={neu.email} onChange={(v) => setNeu({ ...neu, email: v })} />
          <Feld label="Telefon" value={neu.telefon} onChange={(v) => setNeu({ ...neu, telefon: v })} />
          <Feld label="Provisionssatz in %" value={neu.satz}
            onChange={(v) => setNeu({ ...neu, satz: v.replace(/[^\d,.]/g, "") })}
            fehler={neu.satz !== "" && !satzOk ? "Höchstens dein eigener Satz von " + num(eigenerSatz, 0) + " %" : null} />
          <Feld label="Begründung oder Hinweise für die Geschäftsführung" value={neu.notiz}
            onChange={(v) => setNeu({ ...neu, notiz: v })} breit />
        </div>
        <p className="text-xs mt-3" style={{ color: C.muted, maxWidth: "62ch" }}>
          {neu.satz !== "" && !satzOk && (
            <span className="block mb-1" style={{ color: C.warn }}>
              Der Satz darf höchstens deinem eigenen Satz von {num(eigenerSatz, 0)} % entsprechen.
            </span>
          )}
          Der neue Partner wird dir zugeordnet. Du erhältst die Differenz zwischen deinem Satz
          ({num(eigenerSatz, 0)} %) und seinem Satz
          {satzOk ? ", hier " + num(eigenerSatz - satz, 0) + " Prozentpunkte" : ""}.
          Die Geschäftsführung prüft die Anfrage, unterschreibt den Handelsvertretervertrag und
          erzeugt den Einladungslink.
        </p>
        <div className="flex gap-2 mt-5">
          <Btn icon={Send} onClick={senden} disabled={!neu.name.trim() || !mailOk || !satzOk}>
            An die Geschäftsführung senden
          </Btn>
          <Btn variante="hell" onClick={() => setNeu(null)}>Abbrechen</Btn>
        </div>
      </div>
    );

  if (gewaehlt)
    return (
      <div className="space-y-5">
        <div className="flex items-center gap-3">
          <button onClick={() => setAuswahl(null)} style={{ color: C.muted }}><ArrowLeft size={18} /></button>
          <div className="flex-1">
            <div className="text-lg">{gewaehlt.name}</div>
            <div className="text-xs" style={{ color: C.muted }}>angefragt am {datum(gewaehlt.datum)}</div>
          </div>
          <StrukturStatus status={gewaehlt.status} />
        </div>
        <div className="rounded p-5 text-sm space-y-1" style={{ background: C.card, border: "1px solid " + C.line }}>
          <div>{gewaehlt.email}{gewaehlt.telefon ? " · " + gewaehlt.telefon : ""}</div>
          <div>Provisionssatz: {num(gewaehlt.satz, 0)} %
            {gewaehlt.freigabe && gewaehlt.freigabe.satz !== gewaehlt.satz
              ? " · von der Geschäftsführung festgelegt: " + num(gewaehlt.freigabe.satz, 0) + " %" : ""}
          </div>
          {gewaehlt.notiz && <div style={{ color: C.muted }}>{gewaehlt.notiz}</div>}
        </div>
        {gewaehlt.status === "abgelehnt" && (
          <div className="p-4 rounded" style={{ background: "#FCF3F0", border: "1px solid " + C.warn }}>
            <div className="text-sm mb-1" style={{ color: C.warn }}>Abgelehnt</div>
            <p className="text-sm">{gewaehlt.ablehnung || "ohne Begründung"}</p>
          </div>
        )}
        {gewaehlt.status === "freigegeben" && gewaehlt.link && (
          <div className="rounded p-5" style={{ background: C.card, border: "1px solid " + C.ok }}>
            <div className="text-sm mb-1">Einladungslink</div>
            <p className="text-xs mb-3" style={{ color: C.muted }}>
              Freigegeben von {gewaehlt.freigabe.von} am {datum(gewaehlt.freigabe.datum)}. Schick
              den Link an {gewaehlt.name}. Er gilt 30 Tage und nur einmal.
            </p>
            <LinkKopieren url={gewaehlt.link} />
          </div>
        )}
        {gewaehlt.status === "offen" && (
          <Btn variante="hell" onClick={() => {
            setAnfragen(anfragen.map((x) => (x.id === gewaehlt.id ? { ...x, status: "zurueckgezogen" } : x)));
            setAuswahl(null);
          }}>Anfrage zurückziehen</Btn>
        )}
      </div>
    );

  return (
    <div>
      <div className="flex flex-wrap items-center justify-between gap-3 mb-5">
        <p className="text-sm" style={{ color: C.muted, maxWidth: "52ch" }}>
          Neue Vertriebspartner für deine Struktur fragst du hier bei der Geschäftsführung an.
          Nach der Freigabe bekommst du den Einladungslink.
        </p>
        <Btn icon={Plus} onClick={() => setNeu(leer())}>Neuen Partner anfragen</Btn>
      </div>
      {meine.length === 0 ? (
        <div className="rounded p-8 text-center text-sm" style={{ border: "1px dashed " + C.line, color: C.muted }}>
          Noch keine Anfragen.
        </div>
      ) : (
        <div className="rounded overflow-hidden" style={{ background: C.card, border: "1px solid " + C.line }}>
          {meine.map((x, i) => (
            <button key={x.id} onClick={() => setAuswahl(x.id)}
              className="w-full text-left px-4 py-3 flex flex-wrap items-center gap-x-4 gap-y-1"
              style={{ borderTop: i ? "1px solid " + C.line : "none" }}>
              <div className="flex-1 min-w-40">
                <div className="text-sm">{x.name}</div>
                <div className="text-xs" style={{ color: C.muted }}>
                  {num(x.satz, 0)} % · angefragt am {datum(x.datum)}
                </div>
              </div>
              <div className="w-48"><StrukturStatus status={x.status} /></div>
              <ChevronRight size={15} style={{ color: C.muted }} />
            </button>
          ))}
        </div>
      )}
    </div>
  );
}

/* Freigabe einer Strukturanfrage durch die Geschäftsführung */
function StrukturFreigabe({ anfrage, mitarbeiter, setMitarbeiter, strukturanfragen, setStrukturanfragen,
                            user, notieren, onZurueck }) {
  const [satz, setSatz] = useState(String(anfrage.satz));
  const [unterschrift, setUnterschrift] = useState(null);
  const [grund, setGrund] = useState("");
  const [fertig, setFertig] = useState(null);
  const tl = mitarbeiter.find((m) => m.id === anfrage.vonId);
  const s = parseFloat(String(satz).replace(",", "."));
  const satzOk = !isNaN(s) && s > 0 && s <= 50;
  const schonDa = mitarbeiter.some((m) => (m.email || "").toLowerCase() === anfrage.email.toLowerCase());

  const setzAnfrage = (aend) =>
    setStrukturanfragen(strukturanfragen.map((x) => (x.id === anfrage.id ? { ...x, ...aend } : x)));

  const freigeben = () => {
    const code = uid().toUpperCase() + uid().toUpperCase();
    const url = window.location.origin + "/?code=" + code;
    const id = "vp-" + uid();
    const m = {
      id, name: anfrage.name, rolle: "Vertriebspartner", team: anfrage.team || "-",
      satz: s, upline: anfrage.upline || anfrage.vonId, email: anfrage.email,
      telefon: anfrage.telefon || "", status: "eingeladen", passwort: "", bild: null, einladung: code,
      stammdaten: leereStammdaten(),
      vertrag: {
        art: "Handelsvertretervertrag", rolle: "Vertriebspartner", satz: s,
        upline: anfrage.upline || anfrage.vonId, team: anfrage.team || "-",
        anfrageId: anfrage.id, anfrageVon: anfrage.von, anfrageDatum: anfrage.datum,
        gfName: user.name, gfDatum: heute(), gfUnterschrift: unterschrift,
        partnerUnterschrift: null, partnerDatum: null,
      },
    };
    setMitarbeiter([...mitarbeiter, m]);
    setzAnfrage({ status: "freigegeben", mitarbeiterId: id, link: url,
                  freigabe: { von: user.name, datum: heute(), satz: s } });
    if (notieren) notieren("Mitarbeiter", m.name + " auf Anfrage von " + anfrage.von +
      " angelegt mit " + num(s, 0) + " %, Vertrag unterschrieben von " + user.name);
    setFertig(url);
  };

  const ablehnen = () => {
    setzAnfrage({ status: "abgelehnt", ablehnung: grund.trim(), entschieden: { von: user.name, datum: heute() } });
    if (notieren) notieren("Struktur", "Anfrage für " + anfrage.name + " von " + anfrage.von + " abgelehnt");
    onZurueck();
  };

  if (fertig)
    return (
      <div className="rounded p-5" style={{ background: C.card, border: "1px solid " + C.ok }}>
        <div className="flex items-center gap-2 mb-3" style={{ color: C.ok }}>
          <Check size={16} /><span className="text-sm">{anfrage.name} wurde angelegt</span>
        </div>
        <p className="text-sm mb-3" style={{ color: C.muted, maxWidth: "60ch" }}>
          Der Handelsvertretervertrag ist von dir unterschrieben. {anfrage.von} sieht den Link
          ebenfalls in seinen Strukturanfragen. Der neue Partner unterschreibt, bevor er seine
          Stammdaten zur Freigabe einreicht.
        </p>
        <LinkKopieren url={fertig} />
        <div className="mt-3"><Btn variante="hell" onClick={onZurueck}>Fertig</Btn></div>
      </div>
    );

  return (
    <div className="space-y-5">
      <div className="flex items-center gap-3">
        <button onClick={onZurueck} style={{ color: C.muted }}><ArrowLeft size={18} /></button>
        <div className="flex-1">
          <div className="text-lg">Strukturanfrage: {anfrage.name}</div>
          <div className="text-xs" style={{ color: C.muted }}>
            von {anfrage.von} (Satz {tl ? num(tl.satz, 0) : "?"} %) am {datum(anfrage.datum)}
          </div>
        </div>
        <StrukturStatus status={anfrage.status} />
      </div>

      <div className="rounded p-5" style={{ background: C.card, border: "1px solid " + C.line }}>
        <div className="text-sm space-y-1 mb-4">
          <div>{anfrage.email}{anfrage.telefon ? " · " + anfrage.telefon : ""}</div>
          <div style={{ color: C.muted }}>Vertriebspartner · Team {anfrage.team} · zugeordnet an {anfrage.von}</div>
          {anfrage.notiz && <div className="pt-2">{anfrage.notiz}</div>}
        </div>
        {schonDa && (
          <p className="text-xs mb-3" style={{ color: C.warn }}>
            Mit dieser E-Mail gibt es bereits einen Mitarbeiter.
          </p>
        )}
        {anfrage.status === "offen" ? (
          <>
            <div className="sm:max-w-xs">
              <Feld label="Provisionssatz in %" value={satz}
                onChange={(v) => setSatz(v.replace(/[^\d,.]/g, ""))}
                fehler={!satzOk ? "Zwischen 1 und 50 %" : null} />
            </div>
            <p className="text-xs mt-1 mb-4" style={{ color: C.muted }}>
              Vorgeschlagen: {num(anfrage.satz, 0)} %.
              {tl && satzOk ? " " + anfrage.von + " erhält " + num(Math.max(0, (tl.satz || 0) - s), 0) + " Prozentpunkte Overhead." : ""}
            </p>
            <Unterschrift label="Unterschrift Geschäftsführung unter den Handelsvertretervertrag"
              onChange={setUnterschrift} />
            <div className="flex flex-wrap gap-2 mt-5">
              <Btn variante="ok" icon={Check} onClick={freigeben} disabled={!unterschrift || !satzOk || schonDa}>
                Unterschreiben und Einladung erzeugen
              </Btn>
            </div>
            <div className="mt-6 pt-5" style={{ borderTop: "1px solid " + C.line }}>
              <Feld label="Begründung bei Ablehnung" value={grund} onChange={setGrund} breit />
              <div className="mt-2">
                <Btn variante="gefahr" onClick={ablehnen} disabled={!grund.trim()}>Ablehnen</Btn>
              </div>
            </div>
          </>
        ) : anfrage.status === "freigegeben" && anfrage.link ? (
          <LinkKopieren url={anfrage.link} />
        ) : (
          <p className="text-sm" style={{ color: C.muted }}>{anfrage.ablehnung || ""}</p>
        )}
      </div>
    </div>
  );
}

/* Portalsteuerung (nur Geschäftsführung): Zugänge für alle Rollen anlegen und Passwörter setzen.
   Den Zugang legt der Server an (Server-Funktion „einladung“, Aktion zugang_setzen). */
const ALLE_ROLLEN = ["Vertriebspartner", "Teamleiter", "Leitung Vertrieb", "Kalkulation", "Vertragsmanagement",
  "Leadmanagement", "Finanzbuchhaltung", "Beschaffung", "Geschäftsführung"];
const VERTRIEBSROLLEN = ["Vertriebspartner", "Teamleiter", "Leitung Vertrieb"];
const passwortVorschlag = () => {
  const z = "abcdefghjkmnpqrstuvwxyzABCDEFGHJKLMNPQRSTUVWXYZ23456789", sz = "!#+?-";
  const r = crypto.getRandomValues(new Uint32Array(12));
  const t = Array.from(r, (x) => z[x % z.length]);
  t[3] = sz[r[3] % sz.length]; t[8] = String(2 + (r[8] % 8));
  return t.join("");
};
const zugangsText = (name, email, pw) =>
  "Dein Zugang zum EGC-Vertriebsportal\n" + "Name: " + name + "\nAdresse: " + PORTAL_ADRESSE + "\nE-Mail: " + email + "\nPasswort: " + pw
  + "\n\nDas Passwort kannst du nach der Anmeldung im Menü unter „Passwort ändern“ selbst ändern.";

function PasswortFeld({ label, value, onChange }) {
  const regeln = passwortRegeln(value);
  return (
    <div>
      <div className="flex items-end gap-2">
        <div className="flex-1"><Feld label={label} value={value} onChange={onChange} /></div>
        <Btn variante="hell" onClick={() => onChange(passwortVorschlag())}>Vorschlag</Btn>
      </div>
      <div className="mt-1 flex flex-wrap gap-x-4">
        {regeln.map((x) => (
          <span key={x.text} className="text-xs inline-flex items-center gap-1" style={{ color: x.ok ? C.ok : C.muted }}>
            {x.ok ? <Check size={12} /> : <X size={12} />} {x.text}
          </span>
        ))}
      </div>
    </div>
  );
}

function ZugangKopieren({ titel, name, email, pw, onFertig }) {
  const [kopiert, setKopiert] = useState(false);
  const text = zugangsText(name, email, pw);
  return (
    <div className="rounded p-4" style={{ background: "#F1F7F0", border: "1px solid " + C.gruen }}>
      <div className="text-sm flex items-center gap-2 mb-2" style={{ color: C.ok }}><Check size={16} /> {titel}</div>
      <pre className="text-xs whitespace-pre-wrap p-3 rounded mb-3" style={{ background: "#fff", border: "1px solid " + C.line, fontFamily: "inherit" }}>{text}</pre>
      <div className="flex flex-wrap gap-2">
        <Btn icon={Check} onClick={async () => { try { await navigator.clipboard.writeText(text); setKopiert(true); } catch (e) { /* von Hand */ } }}>
          {kopiert ? "Kopiert" : "Zugangsdaten kopieren"}
        </Btn>
        <Btn variante="hell" onClick={onFertig}>Fertig</Btn>
      </div>
      <p className="text-xs mt-2" style={{ color: C.muted }}>Das Passwort wird nirgends gespeichert. Gib es der Person direkt weiter.</p>
    </div>
  );
}

function Portalsteuerung({ mitarbeiter, setMitarbeiter, user, notieren }) {
  const leer = { name: "", email: "", telefon: "", rolle: "Kalkulation", satz: "", upline: "", angestellt: true, frei: true, pw: passwortVorschlag() };
  const [neu, setNeu] = useState(null);
  const [laeuft, setLaeuft] = useState(false);
  const [fehler, setFehler] = useState("");
  const [ergebnis, setErgebnis] = useState(null);
  const [pwFuer, setPwFuer] = useState(null);
  const [pw, setPw] = useState("");
  const [filter, setFilter] = useState("alle");
  const [suche, setSuche] = useState("");

  const vertrieb = neu && VERTRIEBSROLLEN.includes(neu.rolle);
  const koepfe = mitarbeiter.filter((m) => ["Teamleiter", "Leitung Vertrieb"].includes(m.rolle) && m.status === "aktiv");
  const emailFrei = neu && !mitarbeiter.some((m) => String(m.email || "").trim().toLowerCase() === neu.email.trim().toLowerCase());
  const satzWert = neu ? parseFloat(String(neu.satz).replace(",", ".")) : NaN;
  const neuOk = neu && neu.name.trim() && /\S+@\S+\.\S+/.test(neu.email) && emailFrei && passwortRegeln(neu.pw).every((x) => x.ok)
    && (!vertrieb || (!isNaN(satzWert) && satzWert > 0 && satzWert <= 50));

  const anlegen = async () => {
    setLaeuft(true); setFehler("");
    const status = neu.frei ? "aktiv" : "registriert";
    const m = {
      id: "vp-" + uid(), name: neu.name.trim(), rolle: neu.rolle, team: "-",
      satz: vertrieb ? satzWert : 0, upline: vertrieb ? (neu.upline || null) : null,
      email: neu.email.trim().toLowerCase(), telefon: neu.telefon.trim(), status, passwort: "", bild: null,
      stammdaten: leereStammdaten(), angestellt: !vertrieb || !!neu.angestellt,
      ...(status === "aktiv" ? { freigabe: { von: user.name, datum: heute() } } : {}),
    };
    try {
      const { stammdaten, satz, passwort, ...daten } = m;
      await zugangSetzen({ id: m.id, passwort: neu.pw, status, daten });
      setMitarbeiter(mitarbeiter.some((x) => x.id === m.id) ? mitarbeiter.map((x) => (x.id === m.id ? { ...x, ...m } : x)) : [...mitarbeiter, m]);
      if (notieren) notieren("Mitarbeiter", m.name + " als " + m.rolle + " mit Zugang angelegt (Portalsteuerung)");
      setErgebnis({ titel: "Zugang angelegt", name: m.name, email: m.email, pw: neu.pw });
      setNeu(null);
    } catch (e) { setFehler((e && e.message) || String(e)); }
    setLaeuft(false);
  };

  const pwSetzen = async (m) => {
    setLaeuft(true); setFehler("");
    try {
      const st = VERTRIEBSROLLEN.includes(m.rolle) ? "registriert" : "aktiv";
      const r = await zugangSetzen({ id: m.id, passwort: pw, status: st });
      if (m.status === "eingeladen" && r && r.status) setMitarbeiter(mitarbeiter.map((x) => (x.id === m.id ? { ...x, status: r.status } : x)));
      if (notieren) notieren("Zugang", "Passwort für " + m.name + " neu gesetzt (Portalsteuerung)");
      setErgebnis({ titel: "Passwort gesetzt", name: m.name, email: m.email, pw });
      setPwFuer(null); setPw("");
    } catch (e) { setFehler((e && e.message) || String(e)); }
    setLaeuft(false);
  };

  const liste = mitarbeiter
    .filter((m) => !/^t-/.test(m.id))
    .filter((m) => filter === "alle" || m.rolle === filter)
    .filter((m) => !suche.trim() || (m.name + " " + m.email).toLowerCase().includes(suche.trim().toLowerCase()))
    .sort((a, b) => ALLE_ROLLEN.indexOf(a.rolle) - ALLE_ROLLEN.indexOf(b.rolle) || (a.name || "").localeCompare(b.name || ""));
  const statusText = { aktiv: "aktiv", eingeladen: "eingeladen, noch kein Zugang", registriert: "Stammdaten offen", pruefung: "in Prüfung",
    abgelehnt: "zurückgewiesen", gesperrt: "gesperrt" };

  return (
    <div>
      <div className="flex flex-wrap items-center justify-between gap-3 mb-2">
        <h2 className="text-lg">Portalsteuerung</h2>
        {!neu && !ergebnis && <Btn icon={UserPlus} onClick={() => { setNeu({ ...leer }); setFehler(""); }}>Nutzer anlegen</Btn>}
      </div>
      <p className="text-sm mb-5" style={{ color: C.muted, maxWidth: "65ch" }}>
        Zugänge für alle Rollen anlegen und Passwörter setzen. Vertriebspartner kannst du weiterhin auch über eine Einladung
        unter Vertriebsmitarbeiter anlegen, dann vergeben sie ihr Passwort selbst.
      </p>

      {ergebnis && <div className="mb-5"><ZugangKopieren {...ergebnis} onFertig={() => setErgebnis(null)} /></div>}

      {neu && (
        <div className="rounded p-5 mb-5 space-y-4" style={{ background: C.card, border: "1px solid " + C.line }}>
          <div className="text-sm">Neuer Nutzer</div>
          <div className="grid sm:grid-cols-2 gap-4">
            <Feld label="Name" value={neu.name} onChange={(v) => setNeu({ ...neu, name: v })} />
            <Select label="Rolle" value={neu.rolle} options={ALLE_ROLLEN}
              onChange={(v) => setNeu({ ...neu, rolle: v, frei: !VERTRIEBSROLLEN.includes(v), angestellt: !VERTRIEBSROLLEN.includes(v) })} />
            <Feld label="E-Mail (Anmeldename)" value={neu.email} onChange={(v) => setNeu({ ...neu, email: v })}
              fehler={neu.email && !emailFrei ? "Diese E-Mail gibt es schon im Portal." : null} />
            <Feld label="Telefon (freiwillig)" value={neu.telefon} onChange={(v) => setNeu({ ...neu, telefon: v })} />
            {vertrieb && (
              <>
                <Feld label="Provisionssatz in %" value={neu.satz} onChange={(v) => setNeu({ ...neu, satz: v })}
                  fehler={neu.satz !== "" && !(satzWert > 0 && satzWert <= 50) ? "zwischen 0 und 50 %" : null} />
                <Select label="Struktur (Teamleiter oder Leitung)" value={neu.upline}
                  options={[{ value: "", label: "ohne Strukturkopf" }, ...koepfe.map((k) => ({ value: k.id, label: k.name + " · " + k.rolle }))]}
                  onChange={(v) => setNeu({ ...neu, upline: v })} />
              </>
            )}
          </div>
          <PasswortFeld label="Passwort" value={neu.pw} onChange={(v) => setNeu({ ...neu, pw: v })} />
          {vertrieb && (
            <label className="flex items-center gap-2 text-sm">
              <input type="checkbox" checked={!!neu.angestellt} onChange={(e) => setNeu({ ...neu, angestellt: e.target.checked })} />
              Angestellt (Provision wird angezeigt, abgerechnet über die Lohnabrechnung)
            </label>
          )}
          <label className="flex items-start gap-2 text-sm">
            <input type="checkbox" className="mt-1" checked={!!neu.frei} onChange={(e) => setNeu({ ...neu, frei: e.target.checked })} />
            <span>Sofort freischalten
              <span className="block text-xs" style={{ color: C.muted }}>
                {neu.frei ? "Die Person kann direkt mit dem Portal arbeiten."
                  : "Die Person muss zuerst ihre Stammdaten ausfüllen, du gibst sie danach unter Vertriebsmitarbeiter frei."}
              </span></span>
          </label>
          <div className="flex flex-wrap gap-2">
            <Btn icon={Check} onClick={anlegen} disabled={!neuOk || laeuft}>{laeuft ? "Einen Moment …" : "Nutzer mit Zugang anlegen"}</Btn>
            <Btn variante="hell" onClick={() => setNeu(null)} disabled={laeuft}>Abbrechen</Btn>
          </div>
          {fehler && <p className="text-sm" style={{ color: C.warn }}>{fehler}</p>}
        </div>
      )}

      <div className="flex flex-wrap gap-2 mb-3">
        <input value={suche} onChange={(e) => setSuche(e.target.value)} placeholder="Name oder E-Mail suchen"
          className="px-3 py-2 text-sm rounded outline-none flex-1 min-w-48" style={{ border: "1px solid " + C.line, background: C.card }} />
        <select value={filter} onChange={(e) => setFilter(e.target.value)} className="px-3 py-2 text-sm rounded"
          style={{ border: "1px solid " + C.line, background: C.card }}>
          <option value="alle">Alle Rollen</option>
          {ALLE_ROLLEN.map((r) => <option key={r} value={r}>{r}</option>)}
        </select>
      </div>
      <div className="rounded overflow-hidden" style={{ background: C.card, border: "1px solid " + C.line }}>
        {liste.length === 0 && <div className="p-4 text-sm" style={{ color: C.muted }}>Niemand gefunden.</div>}
        {liste.map((m, i) => (
          <div key={m.id} className="px-4 py-3" style={{ borderTop: i ? "1px solid " + C.line : "none" }}>
            <div className="flex flex-wrap items-center gap-x-4 gap-y-2">
              <div className="flex-1 min-w-48">
                <div className="text-sm">{m.name}{m.id === user.id ? " (du)" : ""}</div>
                <div className="text-xs" style={{ color: C.muted }}>{m.rolle} · {m.email || "keine E-Mail"} · {statusText[m.status] || m.status}</div>
              </div>
              {pwFuer !== m.id && (
                <button className="text-sm underline" style={{ color: C.strom }} disabled={!m.email}
                  onClick={() => { setPwFuer(m.id); setPw(passwortVorschlag()); setFehler(""); setErgebnis(null); }}>
                  {m.status === "eingeladen" ? "Zugang mit Passwort anlegen" : "Passwort setzen"}
                </button>
              )}
            </div>
            {pwFuer === m.id && (
              <div className="mt-3 p-3 rounded space-y-3" style={{ background: "#F6F8FA" }}>
                <PasswortFeld label={"Neues Passwort für " + m.name} value={pw} onChange={setPw} />
                <p className="text-xs" style={{ color: C.muted }}>Das bisherige Passwort gilt danach nicht mehr. Angemeldete Geräte bleiben bis zur nächsten Anmeldung angemeldet.</p>
                <div className="flex flex-wrap gap-2">
                  <Btn icon={Check} onClick={() => pwSetzen(m)} disabled={laeuft || !passwortRegeln(pw).every((x) => x.ok)}>
                    {laeuft ? "Einen Moment …" : "Passwort setzen"}</Btn>
                  <Btn variante="hell" onClick={() => setPwFuer(null)} disabled={laeuft}>Abbrechen</Btn>
                </div>
                {fehler && <p className="text-sm" style={{ color: C.warn }}>{fehler}</p>}
              </div>
            )}
          </div>
        ))}
      </div>
    </div>
  );
}

/* Verwaltung der Vertriebsmitarbeiter: anlegen, einladen, Sätze setzen, freigeben */
function Partnerverwaltung({ mitarbeiter, setMitarbeiter, user, notieren, bonus, setBonus,
                             strukturanfragen = [], setStrukturanfragen, firmendaten, setFirmendaten }) {
  const [auswahl, setAuswahl] = useState(null);
  const [anfrageAuswahl, setAnfrageAuswahl] = useState(null);
  const [gfUnterschrift, setGfUnterschrift] = useState(null);
  const [neu, setNeu] = useState(null);
  const [link, setLink] = useState(null);
  const [hinweis, setHinweis] = useState("");
  const [sd, setSd] = useState(null);
  const [bearbeiten, setBearbeiten] = useState(false);

  const istGF = user.rolle === "Geschäftsführung";
  const vertrieb = mitarbeiter.filter((m) =>
    ["Vertriebspartner", "Teamleiter", "Leitung Vertrieb"].includes(m.rolle));
  const koepfe = mitarbeiter.filter((m) => ["Teamleiter", "Leitung Vertrieb"].includes(m.rolle));
  const gewaehlt = mitarbeiter.find((m) => m.id === auswahl);

  const setz = (id, aend) => {
    const m = mitarbeiter.find((x) => x.id === id);
    if (m && notieren) {
      if (aend.satz != null && aend.satz !== m.satz)
        notieren("Provisionssatz", m.name + ": " + num(m.satz, 0) + " % auf " + num(aend.satz, 0) + " % geändert");
      if (aend.upline !== undefined && aend.upline !== m.upline) {
        const neu = mitarbeiter.find((x) => x.id === aend.upline);
        notieren("Struktur", m.name + " zugeordnet an " + (neu ? neu.name : "niemanden"));
      }
      if (aend.status === "aktiv" && m.status !== "aktiv")
        notieren("Freigabe", m.name + " freigeschaltet"
          + (aend.freigabe && aend.freigabe.ohneStammdaten ? " (Stammdaten werden nachgereicht)" : ""));
    }
    setMitarbeiter(mitarbeiter.map((x) => (x.id === id ? { ...x, ...aend } : x)));
  };

  const anlegen = () => {
    const code = uid().toUpperCase() + uid().toUpperCase();
    const m = {
      id: "vp-" + uid(), name: neu.name, rolle: neu.rolle, team: neu.team || "-",
      satz: parseFloat(String(neu.satz).replace(",", ".")) || 0,
      upline: neu.upline || null, email: neu.email, telefon: "",
      status: "eingeladen", passwort: "", bild: null, einladung: code,
      stammdaten: leereStammdaten(), angestellt: neu.beschaeftigung === "angestellt",
    };
    setMitarbeiter([...mitarbeiter, m]);
    if (notieren) notieren("Mitarbeiter", m.name + " angelegt als " + m.rolle + " mit " + m.satz + " %"
      + (m.angestellt ? " (angestellt)" : ""));
    setLink({ name: m.name, url: window.location.origin + "/?code=" + code });
    setNeu(null);
  };

  const freigeben = () => {
    const fehlt = stammdatenLuecken(gewaehlt.stammdaten || {}, !!gewaehlt.angestellt).length > 0;
    setz(gewaehlt.id, { status: "aktiv", pruefHinweis: "",
      freigabe: { von: user.name, datum: heute(), ...(fehlt ? { ohneStammdaten: true } : {}) } });
    setAuswahl(null);
  };
  const zurueckweisen = () => {
    setz(gewaehlt.id, { status: "abgelehnt", pruefHinweis: hinweis });
    setHinweis(""); setAuswahl(null);
  };

  /* ---------- Strukturanfrage eines Teamleiters ---------- */
  const offeneAnfrage = strukturanfragen.find((x) => x.id === anfrageAuswahl);
  if (offeneAnfrage && istGF)
    return (
      <StrukturFreigabe anfrage={offeneAnfrage} mitarbeiter={mitarbeiter} setMitarbeiter={setMitarbeiter}
        strukturanfragen={strukturanfragen} setStrukturanfragen={setStrukturanfragen}
        user={user} notieren={notieren} onZurueck={() => setAnfrageAuswahl(null)} />
    );

  /* ---------- Einladungslink nach dem Anlegen ---------- */
  if (link)
    return (
      <div className="rounded p-5" style={{ background: C.card, border: "1px solid " + C.ok }}>
        <div className="flex items-center gap-2 mb-3" style={{ color: C.ok }}>
          <Check size={16} /><span className="text-sm">{link.name} wurde angelegt</span>
        </div>
        <p className="text-sm mb-3" style={{ color: C.muted, maxWidth: "60ch" }}>
          Schick diesen Link an den neuen Vertriebspartner. Er vergibt darüber sein Passwort und
          hinterlegt anschließend seine Stammdaten.
        </p>
        <div className="p-3 rounded text-sm break-all"
             style={{ background: "#F6F8FA", border: "1px solid " + C.line }}>{link.url}</div>
        <div className="flex flex-wrap gap-2 mt-4">
          <Btn icon={Check} onClick={() => {
            try { navigator.clipboard.writeText(link.url); } catch (e) { /* manuell kopieren */ }
          }}>Link kopieren</Btn>
          <Btn variante="hell" onClick={() => setLink(null)}>Fertig</Btn>
        </div>
      </div>
    );

  /* ---------- Neuen Partner anlegen ---------- */
  if (neu)
    return (
      <div className="rounded p-5" style={{ background: C.card, border: "1px solid " + C.line }}>
        <div className="flex items-center gap-3 mb-5">
          <button onClick={() => setNeu(null)} style={{ color: C.muted }}><ArrowLeft size={18} /></button>
          <h2 className="text-lg">Neuen Vertriebsmitarbeiter anlegen</h2>
        </div>
        <div className="grid sm:grid-cols-2 gap-4">
          <Feld label="Name" value={neu.name} onChange={(v) => setNeu({ ...neu, name: v })} />
          <Feld label="E-Mail" value={neu.email} onChange={(v) => setNeu({ ...neu, email: v })} />
          <Select label="Rolle" value={neu.rolle} onChange={(v) => setNeu({ ...neu, rolle: v })}
            options={["Vertriebspartner", "Teamleiter"]} />
          <Feld label="Team" value={neu.team} onChange={(v) => setNeu({ ...neu, team: v })} placeholder="Süd" />
          <Feld label="Provisionssatz in %" value={neu.satz} onChange={(v) => setNeu({ ...neu, satz: v })} />
          <Select label="Beschäftigung" value={neu.beschaeftigung || "selbststaendig"}
            onChange={(v) => setNeu({ ...neu, beschaeftigung: v })}
            options={[{ value: "selbststaendig", label: "Selbstständig (Handelsvertreter)" },
                      { value: "angestellt", label: "Angestellt bei EGC" }]} />
          <Select label="Zugeordnet an (Overhead)" value={neu.upline || ""}
            onChange={(v) => setNeu({ ...neu, upline: v || null })}
            options={[{ value: "", label: "Keine Zuordnung" },
                      ...koepfe.map((k) => ({ value: k.id, label: k.name + " · " + k.rolle }))]} />
        </div>
        <div className="flex gap-2 mt-6">
          <Btn icon={Send} onClick={anlegen} disabled={!neu.name || !neu.email}>
            Anlegen und Einladungslink erzeugen
          </Btn>
          <Btn variante="hell" onClick={() => setNeu(null)}>Abbrechen</Btn>
        </div>
        {neu.beschaeftigung === "angestellt" && (
          <p className="text-xs mt-3" style={{ color: C.muted, maxWidth: "60ch" }}>
            Angestellt: Provision und Ziele werden im Portal angezeigt wie bei allen anderen.
            Abgerechnet wird über eure Lohnabrechnung. Es gibt keinen Handelsvertretervertrag;
            Gewerbeanmeldung, Bankverbindung und Ausweis sind keine Pflicht.
          </p>
        )}
      </div>
    );

  /* ---------- Einzelner Partner ---------- */
  if (gewaehlt) {
    const daten = sd || gewaehlt.stammdaten || leereStammdaten();
    return (
      <div className="space-y-5">
        <div className="flex items-center gap-3">
          <button onClick={() => { setAuswahl(null); setSd(null); setBearbeiten(false); }} style={{ color: C.muted }}>
            <ArrowLeft size={18} />
          </button>
          <Avatar m={gewaehlt} size={40} />
          <div className="flex-1">
            <div className="text-lg">{gewaehlt.name}</div>
            <div className="text-xs" style={{ color: C.muted }}>
              {gewaehlt.rolle}{gewaehlt.angestellt ? " (angestellt)" : ""} · Team {gewaehlt.team} · {gewaehlt.email}
              {gewaehlt.telefon ? " · " + gewaehlt.telefon : ""}
            </div>
          </div>
          <PartnerStatus status={gewaehlt.status} />
        </div>

        <div className="rounded p-5" style={{ background: C.card, border: "1px solid " + C.line }}>
          <div className="text-sm mb-4">Vergütung und Struktur</div>
          <div className="grid sm:grid-cols-2 gap-4">
            <Feld label="Provisionssatz in %" value={gewaehlt.satz}
              onChange={(v) => setz(gewaehlt.id, { satz: parseFloat(v.replace(",", ".")) || 0 })} />
            {istGF && (
              <Select label="Beschäftigung" value={gewaehlt.angestellt ? "angestellt" : "selbststaendig"}
                onChange={(v) => setz(gewaehlt.id, { angestellt: v === "angestellt" })}
                options={[{ value: "selbststaendig", label: "Selbstständig (Handelsvertreter)" },
                          { value: "angestellt", label: "Angestellt bei EGC" }]} />
            )}
            <Select label="Zugeordnet an (Overhead)" value={gewaehlt.upline || ""}
              onChange={(v) => setz(gewaehlt.id, { upline: v || null })}
              options={[{ value: "", label: "Keine Zuordnung" },
                        ...koepfe.filter((k) => k.id !== gewaehlt.id)
                          .map((k) => ({ value: k.id, label: k.name + " · " + k.rolle }))]} />
          </div>
          {istGF && (
            <div className="mt-4 pt-4" style={{ borderTop: "1px solid " + C.line }}>
              <div className="sm:max-w-xs">
                <Feld label="Eigenakquise-Bonus in Prozentpunkten"
                  value={gewaehlt.eigenBonus !== undefined && gewaehlt.eigenBonus !== ""
                    ? gewaehlt.eigenBonus : ""}
                  placeholder={"Vorgabe: " + num(parseFloat(bonus) || 0, 0)}
                  onChange={(v) => setz(gewaehlt.id, { eigenBonus: v.replace(/[^\d]/g, "") })} />
              </div>
              <p className="text-xs mt-2" style={{ color: C.muted, maxWidth: "60ch" }}>
                Leer lassen, damit die allgemeine Vorgabe gilt. Ein eigener Wert überschreibt sie
                nur für {gewaehlt.name}.
                {gewaehlt.eigenBonus !== undefined && gewaehlt.eigenBonus !== "" && (
                  <button className="ml-2" style={{ color: C.strom }}
                    onClick={() => setz(gewaehlt.id, { eigenBonus: "" })}>zurücksetzen</button>
                )}
              </p>
            </div>
          )}

          {(() => {
            /* Die Sätze rechnen auf die volle Gesamtprovision, bei EGC kommt
               aber nur der Firmenanteil an. Daraus wird ausgezahlt. */
            const v = verteilung(1000, gewaehlt.id, mitarbeiter);
            const beiEgc = (1000 * FIRMENANTEIL) / 100;
            const firma = beiEgc - v.anteile.reduce((t, x) => t + x.betrag, 0);
            return (
              <p className="text-xs mt-3" style={{ color: C.muted }}>
                Bei 1.000 € Gesamtprovision: {v.anteile.map((x) =>
                  x.name + " " + eur(x.betrag)).join(" · ")}
                {istGF ? " · Firma " + eur(firma) + " (von " + eur(beiEgc) + " Firmenanteil, "
                  + num(FIRMENANTEIL, 0) + " %)" : ""}
              </p>
            );
          })()}
        </div>

        {gewaehlt.einladung ? (
          <div className="rounded p-5" style={{ background: C.card, border: "1px solid " + C.line }}>
            <div className="text-sm mb-1">
              {gewaehlt.status === "eingeladen" ? "Einladung offen" : "Zugangslink zum Passwort-Neusetzen offen"}
            </div>
            <p className="text-xs mb-2" style={{ color: C.muted }}>Gilt 30 Tage und nur einmal.</p>
            <div className="p-3 rounded text-sm break-all"
                 style={{ background: "#F6F8FA", border: "1px solid " + C.line }}>
              {window.location.origin}/?code={gewaehlt.einladung}
            </div>
            <div className="mt-3">
              <Btn icon={Check} onClick={() => {
                try { navigator.clipboard.writeText(window.location.origin + "/?code=" + gewaehlt.einladung); }
                catch (e) { /* manuell kopieren */ }
              }}>Link kopieren</Btn>
            </div>
          </div>
        ) : (
          <div className="rounded p-5" style={{ background: C.card, border: "1px solid " + C.line }}>
            <div className="text-sm mb-1">Zugang</div>
            <p className="text-xs mb-3" style={{ color: C.muted, maxWidth: "60ch" }}>
              Passwort vergessen? Ein neuer Zugangslink lässt das Passwort neu vergeben.
            </p>
            <Btn variante="hell" onClick={() =>
              setz(gewaehlt.id, { einladung: uid().toUpperCase() + uid().toUpperCase() })}>
              Neuen Zugangslink erzeugen
            </Btn>
          </div>
        )}

        {istGF && gewaehlt.angestellt && (
          <div className="rounded p-5 text-sm" style={{ background: C.card, border: "1px solid " + C.line, color: C.muted }}>
            Angestellt bei EGC: kein Handelsvertretervertrag, die Provision rechnet ihr über die Lohnabrechnung ab.
          </div>
        )}
        {istGF && !gewaehlt.angestellt && (() => {
          const v = gewaehlt.vertrag || {};
          return (
            <div className="rounded p-5" style={{ background: C.card, border: "1px solid " + C.line }}>
              <div className="flex flex-wrap items-baseline justify-between gap-2 mb-3">
                <span className="text-sm">Handelsvertretervertrag</span>
                {v.gfUnterschrift && (
                  <button className="text-sm" style={{ color: C.strom }}
                    onClick={() => vertragPdf(gewaehlt, mitarbeiter)}>Als PDF</button>
                )}
              </div>
              {v.gfUnterschrift ? (
                <div className="grid sm:grid-cols-2 gap-4 text-xs" style={{ color: C.muted }}>
                  <div>
                    <DateiBild datei={v.gfUnterschrift} hoehe={60} />
                    <div className="mt-1">EGC Energie: {v.gfName}, {datum(v.gfDatum)}</div>
                  </div>
                  <div>
                    {v.partnerUnterschrift
                      ? <DateiBild datei={v.partnerUnterschrift} hoehe={60} />
                      : <div className="py-5">noch nicht unterschrieben</div>}
                    <div className="mt-1">
                      {gewaehlt.name}{v.partnerDatum ? ", " + datum(v.partnerDatum) : ""}
                    </div>
                  </div>
                  <div className="sm:col-span-2">
                    Satz im Vertrag: {num(parseFloat(v.satz) || 0, 0)} %
                    {parseFloat(v.satz) !== parseFloat(gewaehlt.satz)
                      ? " · aktuell " + num(gewaehlt.satz, 0) + " %" : ""}
                  </div>
                </div>
              ) : (
                <>
                  <p className="text-xs mb-3" style={{ color: C.muted }}>
                    Noch nicht von der Geschäftsführung unterschrieben. Satz {num(gewaehlt.satz, 0)} %.
                  </p>
                  <Unterschrift label="Unterschrift Geschäftsführung" onChange={setGfUnterschrift} />
                  <div className="mt-3">
                    <Btn icon={Check} disabled={!gfUnterschrift} onClick={() => {
                      setz(gewaehlt.id, { vertrag: {
                        art: "Handelsvertretervertrag", rolle: gewaehlt.rolle, satz: gewaehlt.satz,
                        upline: gewaehlt.upline || null, team: gewaehlt.team,
                        gfName: user.name, gfDatum: heute(), gfUnterschrift,
                        partnerUnterschrift: v.partnerUnterschrift || null, partnerDatum: v.partnerDatum || null,
                      } });
                      if (notieren) notieren("Vertrag", "Handelsvertretervertrag " + gewaehlt.name + " unterschrieben");
                      setGfUnterschrift(null);
                    }}>Vertrag unterschreiben</Btn>
                  </div>
                </>
              )}
            </div>
          );
        })()}

        {gewaehlt.status !== "eingeladen" && (
          <div className="rounded p-5" style={{ background: C.card, border: "1px solid " + C.line }}>
            <div className="flex items-baseline justify-between mb-4">
              <span className="text-sm">{gewaehlt.angestellt ? "Persönliche Daten (angestellt bei EGC)" : "Stammdaten als Handelsvertreter"}</span>
              {istGF && gewaehlt.status === "aktiv" && (
                <button className="text-sm" style={{ color: C.strom }}
                  onClick={() => { setSd(gewaehlt.stammdaten || leereStammdaten()); setBearbeiten(!bearbeiten); }}>
                  {bearbeiten ? "Bearbeitung beenden" : "Daten ändern"}
                </button>
              )}
            </div>

            <StammdatenFormular sd={daten} setSd={setSd}
              schreiben={istGF && (bearbeiten || gewaehlt.status === "pruefung")} />

            {istGF && (bearbeiten || gewaehlt.status === "pruefung") && (
              <div className="mt-4">
                <Btn variante="hell" onClick={() => { setz(gewaehlt.id, { stammdaten: daten }); setBearbeiten(false); }}>
                  Änderungen speichern
                </Btn>
              </div>
            )}

            {gewaehlt.freigabe && (
              <p className="text-xs mt-4" style={{ color: C.muted }}>
                Freigegeben von {gewaehlt.freigabe.von} am {datum(gewaehlt.freigabe.datum)}
              </p>
            )}
          </div>
        )}

        {istGF && ["pruefung", "registriert"].includes(gewaehlt.status) && (
          <div className="rounded p-5" style={{ background: C.card, border: "1px solid " + C.strom }}>
            <div className="text-sm mb-3">Prüfung und Freigabe</div>
            <p className="text-sm mb-4" style={{ color: C.muted, maxWidth: "60ch" }}>
              {gewaehlt.angestellt
                ? "Angestellt bei EGC: keine Gewerbeanmeldung nötig. Du kannst direkt freischalten."
                : gewaehlt.status === "registriert"
                  ? "Die Stammdaten sind noch nicht eingereicht. Du kannst trotzdem freischalten: Der Partner kann sofort arbeiten, wird bei jeder Anmeldung an die fehlenden Unterlagen erinnert und kann sie selbst nachtragen. Die Freigabe wird im Protokoll vermerkt."
                  : "Prüfe Gewerbeanmeldung, Ausweis und Bankverbindung auf Übereinstimmung mit der Firmierung. Nach der Freigabe kann nur noch die Geschäftsführung diese Daten ändern."}
            </p>
            <label className="block mb-4">
              <span className="block text-xs mb-1" style={{ color: C.muted }}>
                Hinweis bei Nachbesserung
              </span>
              <textarea rows={3} value={hinweis} onChange={(e) => setHinweis(e.target.value)}
                className="w-full px-3 py-2 text-sm rounded outline-none"
                style={{ border: "1px solid " + C.line }} />
            </label>
            <div className="flex flex-wrap gap-2">
              <Btn variante="ok" icon={Check} onClick={freigeben}>
                {gewaehlt.status === "registriert" && !gewaehlt.angestellt ? "Trotzdem freischalten" : "Freischalten"}
              </Btn>
              <Btn variante="gefahr" icon={RotateCcw} onClick={zurueckweisen} disabled={!hinweis.trim()}>
                Zur Nachbesserung zurück
              </Btn>
            </div>
          </div>
        )}
      </div>
    );
  }

  /* ---------- Liste ---------- */
  const zurPruefung = vertrieb.filter((m) => m.status === "pruefung");
  return (
    <div>
      <div className="flex flex-wrap items-center justify-between gap-3 mb-5">
        <p className="text-sm" style={{ color: C.muted, maxWidth: "52ch" }}>
          Neue Mitarbeiter werden hier angelegt und erhalten einen Einladungslink zur Registrierung.
        </p>
        <Btn icon={Plus} onClick={() => setNeu({ name: "", email: "", rolle: "Vertriebspartner", team: "", satz: 25, upline: null })}>
          Vertriebsmitarbeiter anlegen
        </Btn>
      </div>

      {istGF && (
        <div className="rounded p-4 mb-5" style={{ background: C.card, border: "1px solid " + C.line }}>
          <div className="text-sm mb-1">Bonus für Eigenakquise</div>
          <p className="text-xs mb-3" style={{ color: C.muted, maxWidth: "62ch" }}>
            Zusätzliche Prozentpunkte für Kunden, die ein Partner selbst gewonnen hat. Der Bonus geht
            zulasten des Firmenanteils, die Overhead-Provision der Teamleiter bleibt unverändert.
          </p>
          <div className="sm:max-w-xs">
            <Feld label="Bonus in Prozentpunkten" value={bonus}
              onChange={(v) => setBonus(v.replace(/[^\d]/g, ""))} />
          </div>
          <p className="text-xs mt-2" style={{ color: C.muted }}>
            Beispiel bei 1.000 € Gesamtprovision: Ein Partner mit 25 % erhält bei Eigenakquise{" "}
            {eur(10 * (25 + (parseFloat(bonus) || 0)))} statt {eur(250)}.
          </p>
        </div>
      )}

      {istGF && strukturanfragen.some((x) => x.status === "offen") && (
        <div className="rounded overflow-hidden mb-5" style={{ background: C.card, border: "1px solid " + C.gas }}>
          <div className="px-4 py-3 text-sm" style={{ color: C.gas, borderBottom: "1px solid " + C.line }}>
            Strukturanfragen der Teamleiter
          </div>
          {strukturanfragen.filter((x) => x.status === "offen").map((x, i) => (
            <button key={x.id} onClick={() => setAnfrageAuswahl(x.id)}
              className="w-full text-left px-4 py-3 flex items-center gap-4"
              style={{ borderTop: i ? "1px solid " + C.line : "none" }}>
              <div className="flex-1">
                <div className="text-sm">{x.name}</div>
                <div className="text-xs" style={{ color: C.muted }}>
                  {num(x.satz, 0)} % · angefragt von {x.von} am {datum(x.datum)}
                </div>
              </div>
              <ChevronRight size={15} style={{ color: C.muted }} />
            </button>
          ))}
        </div>
      )}

      {istGF && zurPruefung.length > 0 && (
        <div className="rounded p-4 mb-5" style={{ background: "#F6F8FA", border: "1px solid " + C.strom }}>
          <span className="text-sm" style={{ color: C.strom }}>
            {zurPruefung.length} Stammdatensatz{zurPruefung.length === 1 ? "" : "-Sätze"} wartet auf deine Freigabe
          </span>
        </div>
      )}

      <div className="rounded overflow-hidden" style={{ background: C.card, border: "1px solid " + C.line }}>
        {vertrieb.map((m, i) => {
          const kopf = mitarbeiter.find((x) => x.id === m.upline);
          return (
            <button key={m.id} onClick={() => { setAuswahl(m.id); setSd(null); setBearbeiten(false); }}
              className="w-full text-left px-4 py-3 flex flex-wrap items-center gap-x-4 gap-y-2"
              style={{ borderTop: i ? "1px solid " + C.line : "none" }}>
              <Avatar m={m} size={34} />
              <div className="flex-1 min-w-40">
                <div className="text-sm">{m.name}</div>
                <div className="text-xs" style={{ color: C.muted }}>
                  {m.rolle} · {num(m.satz, 0)} % · {kopf ? "Struktur " + kopf.name : "ohne Strukturkopf"}
                </div>
              </div>
              <div className="w-44"><PartnerStatus status={m.status} /></div>
              <ChevronRight size={15} style={{ color: C.muted }} />
            </button>
          );
        })}
      </div>
    </div>
  );
}

/* Eigenes Passwort ändern, für jede Rolle (Seitenleiste unten) */
function PasswortDialog({ onSchliessen }) {
  const [alt, setAlt] = useState("");
  const [pw, setPw] = useState("");
  const [pw2, setPw2] = useState("");
  const [fehler, setFehler] = useState("");
  const [laeuft, setLaeuft] = useState(false);
  const [fertig, setFertig] = useState(false);
  const regeln = passwortRegeln(pw);
  const passt = alt && regeln.every((x) => x.ok) && pw === pw2;
  const absenden = async () => {
    setLaeuft(true); setFehler("");
    try { await passwortAendern(alt, pw); setFertig(true); }
    catch (e) { setFehler((e && e.message) || String(e)); }
    setLaeuft(false);
  };
  return createPortal(
    <div className="flex items-start sm:items-center justify-center px-4"
         style={{ position: "fixed", top: 0, right: 0, bottom: 0, left: 0, zIndex: 50, overflowY: "auto",
                  background: "rgba(10,22,38,0.55)", paddingTop: "max(2rem, env(safe-area-inset-top))", paddingBottom: "2rem" }}
         onClick={(e) => { if (e.target === e.currentTarget && !laeuft) onSchliessen(); }}>
      <div className="w-full max-w-md rounded p-6" style={{ background: C.card, color: C.text, fontFamily: FONT }}>
        <div className="flex items-center justify-between mb-1">
          <h2 className="text-lg">Passwort ändern</h2>
          <button onClick={onSchliessen} style={{ color: C.muted }} title="Schließen"><X size={18} /></button>
        </div>
        {fertig ? (
          <div>
            <p className="text-sm mt-3 flex items-center gap-2" style={{ color: C.ok }}><Check size={16} /> Dein Passwort ist geändert.</p>
            <p className="text-sm mt-2" style={{ color: C.muted }}>Ab sofort meldest du dich mit dem neuen Passwort an, auf allen Geräten.</p>
            <div className="mt-5"><Btn icon={Check} onClick={onSchliessen}>Fertig</Btn></div>
          </div>
        ) : (
          <div>
            <p className="text-sm mb-5" style={{ color: C.muted }}>Zur Sicherheit brauchen wir zuerst dein bisheriges Passwort.</p>
            <div className="space-y-4">
              <Feld label="Bisheriges Passwort" type="password" value={alt} onChange={setAlt} />
              <Feld label="Neues Passwort" type="password" value={pw} onChange={setPw} />
              <Feld label="Neues Passwort wiederholen" type="password" value={pw2} onChange={setPw2} />
            </div>
            <div className="mt-4 space-y-1">
              {regeln.map((x) => (
                <div key={x.text} className="flex items-center gap-2 text-xs" style={{ color: x.ok ? C.ok : C.muted }}>
                  {x.ok ? <Check size={13} /> : <X size={13} />} {x.text}
                </div>
              ))}
              {pw2 && (
                <div className="flex items-center gap-2 text-xs" style={{ color: pw === pw2 ? C.ok : C.muted }}>
                  {pw === pw2 ? <Check size={13} /> : <X size={13} />} Passwörter stimmen überein
                </div>
              )}
            </div>
            <div className="mt-6 flex flex-wrap gap-2">
              <Btn icon={Check} onClick={absenden} disabled={!passt || laeuft}>{laeuft ? "Einen Moment …" : "Passwort ändern"}</Btn>
              <Btn variante="hell" onClick={onSchliessen} disabled={laeuft}>Abbrechen</Btn>
            </div>
            {fehler && <p className="text-sm mt-4" style={{ color: C.warn }}>{fehler}</p>}
            <p className="text-xs mt-5" style={{ color: C.muted }}>
              Bisheriges Passwort vergessen? Dann melde dich bei der Geschäftsführung, du bekommst einen neuen Zugangslink.
            </p>
          </div>
        )}
      </div>
    </div>,
    document.body
  );
}

/* Registrierung über den Einladungslink: Passwort vergeben */
function Registrierung({ einladung, onFertig, onAbbruch }) {
  const [pw, setPw] = useState("");
  const [pw2, setPw2] = useState("");
  const [fehler, setFehler] = useState("");
  const [laeuft, setLaeuft] = useState(false);
  const regeln = passwortRegeln(pw);
  const passt = regeln.every((r) => r.ok) && pw === pw2;

  const absenden = async () => {
    setLaeuft(true); setFehler("");
    try { await onFertig(pw); } catch (e) { setFehler((e && e.message) || String(e)); }
    setLaeuft(false);
  };

  return (
    <div className="min-h-screen flex items-center justify-center px-4"
         style={{ background: C.ink, fontFamily: FONT, paddingTop: "env(safe-area-inset-top)", paddingBottom: "env(safe-area-inset-bottom)" }}>
      <div className="w-full max-w-md">
        <img src={LOGO} alt="EGC Energie" className="w-44 mx-auto mb-8" />
        <div className="rounded p-6" style={{ background: C.card }}>
          <h1 className="text-lg mb-1">{einladung.art === "reset" ? "Neues Passwort, " + einladung.name : "Willkommen, " + einladung.name}</h1>
          <p className="text-sm mb-1" style={{ color: C.muted }}>
            {einladung.art === "reset" ? "Vergib ein neues Passwort für deinen Zugang. Das bisherige gilt danach nicht mehr."
              : "Vergib ein Passwort für deinen Zugang zum Vertriebsportal."}
          </p>
          <p className="text-sm mb-5" style={{ color: C.muted }}>
            Deine Anmeldung: <span style={{ color: C.text }}>{einladung.email}</span>
          </p>

          <div className="space-y-4">
            <Feld label="Passwort" type="password" value={pw} onChange={setPw} />
            <Feld label="Passwort wiederholen" type="password" value={pw2} onChange={setPw2} />
          </div>

          <div className="mt-4 space-y-1">
            {regeln.map((r) => (
              <div key={r.text} className="flex items-center gap-2 text-xs"
                   style={{ color: r.ok ? C.ok : C.muted }}>
                {r.ok ? <Check size={13} /> : <X size={13} />} {r.text}
              </div>
            ))}
            {pw2 && (
              <div className="flex items-center gap-2 text-xs" style={{ color: pw === pw2 ? C.ok : C.muted }}>
                {pw === pw2 ? <Check size={13} /> : <X size={13} />} Passwörter stimmen überein
              </div>
            )}
          </div>

          <div className="mt-6">
            <Btn icon={Check} onClick={absenden} disabled={!passt || laeuft}>
              {laeuft ? "Einen Moment …" : einladung.art === "reset" ? "Neues Passwort speichern und anmelden" : "Passwort setzen und anmelden"}
            </Btn>
          </div>
          {fehler && <p className="text-sm mt-4" style={{ color: C.warn }}>{fehler}</p>}
          <button className="text-xs mt-4" style={{ color: C.muted }} onClick={onAbbruch}>
            Zurück zur Anmeldung
          </button>
        </div>
      </div>
    </div>
  );
}

/* Anmeldemaske: Anmeldung über Supabase, Einladung über die Server-Funktion */
function Login({ onAngemeldet, onEinladung, startCode }) {
  const [email, setEmail] = useState("");
  const [pw, setPw] = useState("");
  const [code, setCode] = useState(startCode || "");
  const [fehler, setFehler] = useState("");
  const [laeuft, setLaeuft] = useState(false);
  const [modus, setModus] = useState(startCode ? "code" : "login");

  const einloggen = async () => {
    setLaeuft(true); setFehler("");
    try {
      await anmelden(email, pw);
      await onAngemeldet();
    } catch (e) {
      const t = (e && e.message) || "";
      setFehler(/invalid login credentials/i.test(t) ? "E-Mail oder Passwort stimmt nicht."
        : /fetch|network/i.test(t) ? "Keine Verbindung zum Server. Bitte Netz prüfen."
        : "Anmeldung nicht möglich: " + t);
    }
    setLaeuft(false);
  };

  const [gesendet, setGesendet] = useState(false);
  const vergessen = async () => {
    setLaeuft(true); setFehler("");
    try { await passwortVergessen(email); setGesendet(true); }
    catch (e) { setFehler(/fetch|network/i.test((e && e.message) || "") ? "Keine Verbindung zum Server. Bitte Netz prüfen." : (e && e.message) || String(e)); }
    setLaeuft(false);
  };

  const einloesen = async () => {
    setLaeuft(true); setFehler("");
    try {
      const c = code.trim().toUpperCase();
      const info = await einladungPruefen(c);
      onEinladung({ ...info, code: c });
    } catch (e) { setFehler((e && e.message) || String(e)); }
    setLaeuft(false);
  };

  return (
    <div className="min-h-screen flex items-center justify-center px-4"
         style={{ background: C.ink, fontFamily: FONT, paddingTop: "env(safe-area-inset-top)", paddingBottom: "env(safe-area-inset-bottom)" }}>
      <div className="w-full max-w-md">
        <img src={LOGO} alt="EGC Energie" className="w-44 mx-auto mb-8" />
        <div className="rounded p-6" style={{ background: C.card }}>
          <div className="flex gap-1 mb-5">
            {[["login", "Anmelden"], ["code", "Einladung einlösen"]].map(([id, label]) => (
              <button key={id} onClick={() => { setModus(id); setFehler(""); }}
                className="px-3 py-1.5 text-sm rounded"
                style={{
                  background: (modus === id || (id === "login" && modus === "vergessen")) ? C.ink : "transparent",
                  color: (modus === id || (id === "login" && modus === "vergessen")) ? "#fff" : C.muted,
                  border: "1px solid " + ((modus === id || (id === "login" && modus === "vergessen")) ? C.ink : C.line),
                }}>{label}</button>
            ))}
          </div>

          {modus === "login" ? (
            <div className="space-y-4">
              <Feld label="E-Mail" value={email} onChange={setEmail} placeholder="name@egc-energie.de" />
              <Feld label="Passwort" type="password" value={pw} onChange={setPw} />
              <Btn onClick={einloggen} disabled={!email || !pw || laeuft}>
                {laeuft ? "Einen Moment …" : "Anmelden"}
              </Btn>
              <button className="block text-sm underline" style={{ color: C.muted }}
                onClick={() => { setModus("vergessen"); setFehler(""); setGesendet(false); }}>Passwort vergessen?</button>
            </div>
          ) : modus === "vergessen" ? (
            gesendet ? (
              <div className="space-y-3">
                <p className="text-sm flex items-start gap-2" style={{ color: C.ok }}><Check size={16} className="shrink-0 mt-0.5" />
                  Wenn diese Adresse im Portal hinterlegt ist, kommt gleich eine E-Mail mit einem Link.</p>
                <p className="text-sm" style={{ color: C.muted }}>
                  Über den Link vergibst du dein neues Passwort selbst. Er gilt zwei Stunden. Schau auch im Spam-Ordner nach.
                </p>
                <button className="text-sm underline" style={{ color: C.muted }} onClick={() => setModus("login")}>Zurück zur Anmeldung</button>
              </div>
            ) : (
              <div className="space-y-4">
                <p className="text-sm" style={{ color: C.muted }}>Gib deine E-Mail-Adresse ein. Wir schicken dir einen Link, mit dem du ein neues Passwort vergibst.</p>
                <Feld label="E-Mail" value={email} onChange={setEmail} placeholder="name@egc-energie.de" />
                <Btn onClick={vergessen} disabled={!/\S+@\S+\.\S+/.test(email) || laeuft}>
                  {laeuft ? "Einen Moment …" : "Link zum Neusetzen anfordern"}
                </Btn>
                <button className="block text-sm underline" style={{ color: C.muted }} onClick={() => setModus("login")}>Zurück zur Anmeldung</button>
              </div>
            )
          ) : (
            <div className="space-y-4">
              <Feld label="Einladungscode aus deinem Link" value={code} onChange={setCode}
                placeholder="Code hinter ?code= im Link" />
              <Btn onClick={einloesen} disabled={!code || laeuft}>
                {laeuft ? "Einen Moment …" : "Weiter zur Registrierung"}
              </Btn>
            </div>
          )}

          {fehler && <p className="text-sm mt-4" style={{ color: C.warn }}>{fehler}</p>}

          <div className="mt-6 pt-4" style={{ borderTop: "1px solid " + C.line }}>
            <p className="text-xs" style={{ color: C.muted }}>{VERSION_ANZEIGE}</p>
          </div>
        </div>
      </div>
    </div>
  );
}

/* Leads aus Social Media, Tippgebern oder Kaltakquise */
function Leads({ leads, setLeads, mitarbeiter, user, onUebernehmen, onGelesen }) {
  const [auswahl, setAuswahl] = useState(null);
  const [entwurf, setEntwurf] = useState(null);
  const [zieht, setZieht] = useState(null);
  const [ueber, setUeber] = useState(null);

  const [modus, setModus] = useState("kanban");
  const [zeitraum, setZeitraum] = useState("alle");
  const [tag, setTag] = useState(heute());
  const [quelle, setQuelle] = useState("alle");

  /* Sehen alle Leads: Leitung und Geschäftsführung.
     Anlegen darf jeder im Vertrieb, zuweisen an andere nur ab Teamleiter aufwärts. */
  const sichtAlle = ["Leitung Vertrieb", "Geschäftsführung", "Leadmanagement"].includes(user.rolle);
  const darfAnlegen = ["Vertriebspartner", "Teamleiter", "Leitung Vertrieb", "Geschäftsführung",
    "Leadmanagement"].includes(user.rolle);
  const darfZuweisen = ["Teamleiter", "Leitung Vertrieb", "Geschäftsführung", "Leadmanagement"]
    .includes(user.rolle);
  const meineIds = user.rolle === "Teamleiter"
    ? [user.id, ...strukturUnter(user.id, mitarbeiter).map((m) => m.id)]
    : [user.id];
  const eigene = sichtAlle ? leads : leads.filter((l) => meineIds.includes(l.zugewiesen));
  const sichtbar = eigene.filter((l) =>
    imZeitraum(l.angelegt, zeitraum, tag) && (quelle === "alle" || l.quelle === quelle));
  const empfaenger = (sichtAlle
    ? mitarbeiter.filter((m) =>
        ["Vertriebspartner", "Teamleiter", "Leitung Vertrieb"].includes(m.rolle))
    : [user, ...strukturUnter(user.id, mitarbeiter)]
  ).filter((m) => m.status === "aktiv");
  const lead = leads.find((l) => l.id === auswahl);

  const setz = (id, aend) => setLeads(leads.map((l) => {
    if (l.id !== id) return l;
    const neu = { ...l, ...aend };
    if (aend.status === "auftrag" && !neu.abschlussAm) neu.abschlussAm = heute();
    if (aend.status && aend.status !== "auftrag") neu.abschlussAm = "";
    return neu;
  }));
  const oeffnen = (l) => {
    setAuswahl(l.id);
    if (!l.gelesen && l.zugewiesen === user.id) onGelesen(l.id);
  };

  const speichern = () => {
    const vorhanden = leads.some((l) => l.id === entwurf.id);
    const fertig = { ...entwurf };
    /* Wer nicht zuweisen darf, legt Leads für sich selbst an */
    if (!darfZuweisen && !fertig.zugewiesen) {
      fertig.zugewiesen = user.id;
      fertig.zugewiesenVon = user.name;
      fertig.zugewiesenAm = heute();
      fertig.gelesen = true;
    }
    if (fertig.zugewiesen === user.id) fertig.gelesen = true;
    if (fertig.zugewiesen && !fertig.zugewiesenAm) {
      fertig.zugewiesenVon = user.name;
      fertig.zugewiesenAm = heute();
      fertig.gelesen = false;
    }
    setLeads(vorhanden ? leads.map((l) => (l.id === fertig.id ? fertig : l)) : [fertig, ...leads]);
    setEntwurf(null);
  };

  /* ---------- Formular ---------- */
  if (entwurf) {
    const setF = (k, v) => setEntwurf({ ...entwurf, [k]: v });
    return (
      <div>
        <div className="flex items-center gap-3 mb-5">
          <button onClick={() => setEntwurf(null)} style={{ color: C.muted }}><ArrowLeft size={18} /></button>
          <h2 className="text-lg">{leads.some((l) => l.id === entwurf.id) ? "Lead bearbeiten" : "Neuen Lead einspielen"}</h2>
        </div>

        <div className="space-y-5">
          <div className="rounded p-5" style={{ background: C.card, border: "1px solid " + C.line }}>
            <div className="text-sm mb-4">Unternehmen und Ansprechpartner</div>
            <div className="grid sm:grid-cols-2 gap-4">
              <Feld label="Firma" value={entwurf.firma} onChange={(v) => setF("firma", v)} breit />
              <Feld label="Straße und Hausnummer" value={entwurf.strasse} onChange={(v) => setF("strasse", v)} breit />
              <Feld label="PLZ" value={entwurf.plz} onChange={(v) => setF("plz", v)} />
              <Feld label="Ort" value={entwurf.ort} onChange={(v) => setF("ort", v)} />
              <Feld label="Ansprechpartner" value={entwurf.ansprechpartner} onChange={(v) => setF("ansprechpartner", v)} />
              <Feld label="Position" value={entwurf.position} onChange={(v) => setF("position", v)} />
              <Feld label="Telefon" value={entwurf.telefon} onChange={(v) => setF("telefon", v)} />
              <Feld label="E-Mail" value={entwurf.email} onChange={(v) => setF("email", v)} />
            </div>
          </div>

          <div className="rounded p-5" style={{ background: C.card, border: "1px solid " + C.line }}>
            <div className="text-sm mb-4">Verbrauch und aktuelle Versorgung</div>
            <div className="grid sm:grid-cols-2 gap-4">
              <Feld label="Jahresverbrauch Strom in kWh" value={entwurf.verbrauchStrom} zahl
                onChange={(v) => setF("verbrauchStrom", v)} />
              <Feld label="Jahresverbrauch Erdgas in kWh" value={entwurf.verbrauchGas} zahl
                onChange={(v) => setF("verbrauchGas", v)} />
              <Feld label="Vertrag Strom läuft bis" type="date" value={entwurf.laufzeitStrom}
                onChange={(v) => setF("laufzeitStrom", v)} />
              <Feld label="Vertrag Erdgas läuft bis" type="date" value={entwurf.laufzeitGas}
                onChange={(v) => setF("laufzeitGas", v)} />
              <Feld label="Aktuelle Beschaffung" value={entwurf.beschaffung}
                onChange={(v) => setF("beschaffung", v)}
                placeholder="z. B. Festpreis über Stadtwerke seit 2024" breit />
            </div>
            <label className="flex items-center gap-3 text-sm mt-4">
              <input type="checkbox" checked={!!entwurf.dienstleister}
                onChange={(e) => setF("dienstleister", e.target.checked)} style={{ accentColor: C.ink }} />
              Kunde arbeitet bereits mit einem Energiedienstleister
            </label>
            {entwurf.dienstleister && (
              <div className="mt-4">
                <Feld label="Welcher Dienstleister?" value={entwurf.dienstleisterName}
                  onChange={(v) => setF("dienstleisterName", v)} />
              </div>
            )}
          </div>

          <div className="rounded p-5" style={{ background: C.card, border: "1px solid " + C.line }}>
            <div className="text-sm mb-4">Herkunft und Termin</div>
            <div className="grid sm:grid-cols-2 gap-4">
              <Select label="Lead generiert über" value={entwurf.quelle}
                onChange={(v) => setF("quelle", v)} options={LEAD_QUELLEN} />
              <Feld label="Details zur Herkunft" value={entwurf.quelleDetail}
                onChange={(v) => setF("quelleDetail", v)}
                placeholder="Kampagne, Tippgeber, Kontaktanlass" />
              <Feld label="Termin am" type="date" value={entwurf.terminDatum}
                onChange={(v) => setF("terminDatum", v)} />
              <Feld label="Uhrzeit" value={entwurf.terminZeit}
                onChange={(v) => setF("terminZeit", v)} placeholder="14:30" />
              <Select label="Terminform" value={entwurf.terminArt}
                onChange={(v) => setF("terminArt", v)} options={TERMINARTEN} breit />
            </div>
            <label className="block mt-4">
              <span className="block text-xs mb-1" style={{ color: C.muted }}>Bemerkungen</span>
              <textarea rows={3} value={entwurf.bemerkung} onChange={(e) => setF("bemerkung", e.target.value)}
                className="w-full px-3 py-2 text-sm rounded outline-none"
                style={{ border: "1px solid " + C.line }} />
            </label>
          </div>

          <div className="rounded p-5" style={{ background: C.card, border: "1px solid " + C.line }}>
            <div className="text-sm mb-1">Unterlagen</div>
            <p className="text-xs mb-4" style={{ color: C.muted }}>
              Versorgerabrechnungen, Lastgänge und alles Weitere als PDF, Excel oder CSV.
            </p>
            <div className="space-y-2 mb-3">
              {entwurf.dateien.map((d, i) => (
                <div key={i} className="flex items-center gap-2">
                  <div className="flex-1 min-w-0"><DateiChip datei={d} /></div>
                  <button onClick={() => setF("dateien", entwurf.dateien.filter((_, x) => x !== i))}
                    style={{ color: C.muted }}><X size={15} /></button>
                </div>
              ))}
            </div>
            <label className="flex items-center gap-2 px-3 py-2 rounded text-sm cursor-pointer"
                   style={{ border: "1px dashed " + C.line, color: C.muted, background: "#fff" }}>
              <Upload size={14} /> Dateien hinzufügen
              <input type="file" multiple className="hidden"
                onChange={(e) => {
                  Array.from(e.target.files || []).forEach((f) =>
                    dateiLesen(f, (d) => setEntwurf((v) => ({ ...v, dateien: [...v.dateien, d] }))));
                }} />
            </label>
          </div>

          <div className="rounded p-5" style={{ background: C.card, border: "1px solid " + C.line }}>
            <div className="text-sm mb-4">Zuweisung</div>
            {!darfZuweisen ? (
              <p className="text-sm" style={{ color: C.muted }}>
                Der Lead läuft auf dich. Teamleiter und Vertriebsleitung sehen ihn in ihren Übersichten mit.
              </p>
            ) : (
            <Select label="Lead zuweisen an" value={entwurf.zugewiesen || ""}
              onChange={(v) => setF("zugewiesen", v || null)}
              options={[{ value: "", label: "Noch nicht zuweisen" },
                        ...empfaenger.map((m) => ({
                          value: m.id,
                          label: (m.id === user.id ? m.name + " (ich)" : m.name) + " · " + m.rolle + " · Team " + m.team,
                        }))]} />
            )}
            {darfZuweisen && (
              <p className="text-xs mt-2" style={{ color: C.muted }}>
                Der Empfänger sieht den Lead sofort in seiner Übersicht, markiert als neu.
                {!sichtAlle ? " Du kannst innerhalb deiner Struktur zuweisen." : ""}
              </p>
            )}
          </div>

          <div className="flex gap-2">
            <Btn icon={Check} onClick={speichern} disabled={!entwurf.firma}>Lead speichern</Btn>
            <Btn variante="hell" onClick={() => setEntwurf(null)}>Abbrechen</Btn>
          </div>
        </div>
      </div>
    );
  }

  /* ---------- Einzelansicht ---------- */
  if (lead) {
    const inhaber = mitarbeiter.find((m) => m.id === lead.zugewiesen);
    const st = LEAD_STATUS[leadSpalte(lead)];
    const Zeile = ({ k, v }) => (
      <div className="flex justify-between gap-4 py-1.5 text-sm" style={{ borderBottom: "1px solid " + C.line }}>
        <span style={{ color: C.muted }}>{k}</span>
        <span className="text-right" style={{ fontVariantNumeric: "tabular-nums" }}>{v || "–"}</span>
      </div>
    );
    return (
      <div>
        <div className="flex items-center gap-3 mb-1">
          <button onClick={() => setAuswahl(null)} style={{ color: C.muted }}><ArrowLeft size={18} /></button>
          <h2 className="text-lg">{lead.firma}</h2>
          <span className="inline-flex items-center gap-1.5 text-xs" style={{ color: st.color }}>
            <span className="w-2 h-2 rounded-full" style={{ background: st.color }} />{st.label}
          </span>
        </div>
        <p className="text-sm mb-4 ml-8" style={{ color: C.muted }}>
          {lead.id} · {lead.quelle}{lead.quelleDetail ? " · " + lead.quelleDetail : ""} · eingespielt {datum(lead.angelegt)}
        </p>

        <div className="rounded p-4 mb-5" style={{ background: C.card, border: "1px solid " + st.color }}>
          <div className="sm:max-w-xs">
            <Select label="Aktuelle Phase" value={leadSpalte(lead)}
              onChange={(v) => setz(lead.id, { status: v })}
              options={LEAD_SPALTEN.map((sp) => ({ value: sp.id, label: sp.label }))} />
          </div>
          {lead.abschlussAm && (
            <p className="text-xs mt-2" style={{ color: C.muted }}>
              Abschluss am {datum(lead.abschlussAm)} · {num(tageZwischen(lead.angelegt, lead.abschlussAm) || 0)} Tage nach Eingang
            </p>
          )}
        </div>

        <div className="grid lg:grid-cols-3 gap-5">
          <div className="lg:col-span-2 space-y-5 min-w-0">
            <div className="rounded p-5" style={{ background: C.card, border: "1px solid " + C.line }}>
              <div className="text-sm mb-3">Verbrauch und Versorgung</div>
              <div className="grid sm:grid-cols-2 gap-x-8">
                <Zeile k="Strom" v={lead.verbrauchStrom ? num(parseFloat(lead.verbrauchStrom)) + " kWh" : "–"} />
                <Zeile k="Erdgas" v={lead.verbrauchGas ? num(parseFloat(lead.verbrauchGas)) + " kWh" : "–"} />
                <Zeile k="Vertrag Strom bis" v={datum(lead.laufzeitStrom)} />
                <Zeile k="Vertrag Erdgas bis" v={datum(lead.laufzeitGas)} />
                <Zeile k="Aktuelle Beschaffung" v={lead.beschaffung} />
                <Zeile k="Dienstleister" v={lead.dienstleister ? (lead.dienstleisterName || "ja") : "keiner"} />
              </div>
            </div>

            <div className="rounded p-5" style={{ background: C.card, border: "1px solid " + C.line }}>
              <div className="text-sm mb-3">Termin</div>
              <div className="grid sm:grid-cols-2 gap-x-8">
                <Zeile k="Datum" v={lead.terminDatum ? datum(lead.terminDatum) + (lead.terminZeit ? ", " + lead.terminZeit + " Uhr" : "") : "noch offen"} />
                <Zeile k="Form" v={lead.terminArt} />
              </div>
              {lead.bemerkung && (
                <p className="text-sm mt-4 p-3 rounded" style={{ background: "#F6F8FA" }}>{lead.bemerkung}</p>
              )}
            </div>

            {lead.dateien.length > 0 && (
              <div className="rounded p-5" style={{ background: C.card, border: "1px solid " + C.line }}>
                <div className="text-sm mb-3">Unterlagen</div>
                <div className="space-y-2">
                  {lead.dateien.map((d, i) => <DateiChip key={i} datei={d} />)}
                </div>
              </div>
            )}

            <div className="rounded p-5" style={{ background: C.card, border: "1px solid " + C.line }}>
              <div className="flex flex-wrap gap-2">
                <Btn icon={Plus} onClick={() => { setz(lead.id, { status: "angebot" }); onUebernehmen(lead); }}>
                  Angebotsanfrage aus Lead erstellen
                </Btn>
                {(sichtAlle || lead.zugewiesen === user.id) && (
                  <Btn variante="hell" onClick={() => setEntwurf(lead)}>Lead bearbeiten</Btn>
                )}
              </div>
            </div>
          </div>

          <div className="space-y-5 min-w-0">
            <div className="rounded p-4" style={{ background: C.card, border: "1px solid " + C.line }}>
              <div className="text-sm mb-3">Kontakt</div>
              <Zeile k="Ansprechpartner" v={lead.ansprechpartner} />
              <Zeile k="Position" v={lead.position} />
              <Zeile k="Telefon" v={lead.telefon} />
              <Zeile k="E-Mail" v={lead.email} />
              <Zeile k="Anschrift" v={[lead.strasse, lead.plz + " " + lead.ort].filter(Boolean).join(", ")} />
            </div>

            <div className="rounded p-4" style={{ background: C.card, border: "1px solid " + C.line }}>
              <div className="text-sm mb-3">Zuweisung</div>
              {inhaber ? (
                <div className="flex items-center gap-3">
                  <Avatar m={inhaber} size={34} />
                  <div>
                    <div className="text-sm">{inhaber.name}</div>
                    <div className="text-xs" style={{ color: C.muted }}>
                      {inhaber.rolle} · von {lead.zugewiesenVon} am {datum(lead.zugewiesenAm)}
                    </div>
                  </div>
                </div>
              ) : (
                <p className="text-sm" style={{ color: C.muted }}>Noch niemandem zugewiesen.</p>
              )}
            </div>
          </div>
        </div>
      </div>
    );
  }

  /* ---------- Kanban ---------- */
  const Karte = ({ l }) => {
    const inhaber = mitarbeiter.find((m) => m.id === l.zugewiesen);
    const neu = !l.gelesen && l.zugewiesen === user.id;
    const menge = (parseFloat(l.verbrauchStrom) || 0) + (parseFloat(l.verbrauchGas) || 0);
    return (
      <div
        draggable
        onDragStart={(e) => { setZieht(l.id); e.dataTransfer.effectAllowed = "move"; }}
        onDragEnd={() => setZieht(null)}
        className="rounded p-3 mb-2"
        style={{
          background: neu ? "#F1F7F0" : "#fff",
          border: "1px solid " + (neu ? C.ok : C.line),
          opacity: zieht === l.id ? 0.4 : 1,
          cursor: "grab",
        }}>
        <button onClick={() => oeffnen(l)} className="w-full text-left">
          <div className="text-sm flex items-start gap-2">
            <span className="flex-1">{l.firma}</span>
            {neu && <span className="text-xs px-1.5 rounded" style={{ background: C.ok, color: "#fff" }}>neu</span>}
          </div>
          <div className="text-xs mt-1" style={{ color: C.muted }}>
            {l.ort} · {l.quelle}
          </div>
          <div className="flex items-center justify-between mt-2 text-xs" style={{ color: C.muted }}>
            <span style={{ fontVariantNumeric: "tabular-nums" }}>{num(menge)} kWh</span>
            {l.terminDatum && <span>{datum(l.terminDatum)}</span>}
          </div>
          {inhaber && (sichtAlle || inhaber.id !== user.id) && (
            <div className="flex items-center gap-2 mt-2 pt-2" style={{ borderTop: "1px solid " + C.line }}>
              <Avatar m={inhaber} size={20} />
              <span className="text-xs truncate" style={{ color: C.muted }}>{inhaber.name}</span>
            </div>
          )}
        </button>

        <div className="mt-2">
          <select
            value={leadSpalte(l)}
            onChange={(e) => setz(l.id, { status: e.target.value })}
            className="w-full px-2 py-1 text-xs rounded outline-none"
            style={{ border: "1px solid " + C.line, color: C.muted, background: "#F6F8FA" }}>
            {LEAD_SPALTEN.map((sp) => (
              <option key={sp.id} value={sp.id}>{sp.label}</option>
            ))}
          </select>
        </div>
      </div>
    );
  };

  return (
    <div>
      <div className="flex flex-wrap items-center justify-between gap-3 mb-4">
        <div className="flex gap-1">
          {[["kanban", "Board"], ["liste", "Liste"], ["auswertung", "Auswertung"]].map(([id, label]) => (
            <button key={id} onClick={() => setModus(id)}
              className="px-3 py-1.5 text-sm rounded"
              style={{
                background: modus === id ? C.ink : "transparent",
                color: modus === id ? "#fff" : C.muted,
                border: "1px solid " + (modus === id ? C.ink : C.line),
              }}>{label}</button>
          ))}
        </div>
        {darfAnlegen && (
          <Btn icon={Plus} onClick={() => setEntwurf({
            ...leererLead(),
            quelle: darfZuweisen ? "Kaltakquise" : "Eigenakquise",
            zugewiesen: darfZuweisen ? null : user.id,
          })}>Lead anlegen</Btn>
        )}
      </div>

      <div className="rounded p-3 mb-5 grid sm:grid-cols-3 gap-3"
           style={{ background: C.card, border: "1px solid " + C.line }}>
        <Select label="Eingespielt im Zeitraum" value={zeitraum} onChange={setZeitraum} options={ZEITRAEUME} />
        {zeitraum === "tag" ? (
          <Feld label="Tag" type="date" value={tag} onChange={setTag} />
        ) : (
          <div className="hidden sm:block" />
        )}
        <Select label="Herkunft des Leads" value={quelle} onChange={setQuelle}
          options={[{ value: "alle", label: "Alle Quellen" }, ...LEAD_QUELLEN]} />
      </div>

      {modus === "auswertung" ? (
        <LeadAuswertung leads={sichtbar} mitarbeiter={mitarbeiter} user={user} darfAlles={sichtAlle} />
      ) : sichtbar.length === 0 ? (
        <div className="rounded p-8 text-center text-sm"
             style={{ border: "1px dashed " + C.line, color: C.muted }}>
          Keine Leads im gewählten Zeitraum.
        </div>
      ) : modus === "liste" ? (
        <div className="rounded overflow-hidden" style={{ background: C.card, border: "1px solid " + C.line }}>
          {[...sichtbar].sort((a, b) => (b.angelegt || "").localeCompare(a.angelegt || "")).map((l, i) => {
            const sp = LEAD_STATUS[leadSpalte(l)];
            const inhaber = mitarbeiter.find((m) => m.id === l.zugewiesen);
            const neuL = !l.gelesen && l.zugewiesen === user.id;
            return (
              <button key={l.id} onClick={() => oeffnen(l)}
                className="w-full text-left px-4 py-3 flex flex-wrap items-center gap-x-4 gap-y-1"
                style={{ borderTop: i ? "1px solid " + C.line : "none",
                         background: neuL ? "#F1F7F0" : "transparent" }}>
                <div className="flex-1 min-w-40">
                  <div className="text-sm flex items-center gap-2">
                    {l.firma}
                    {neuL && <span className="text-xs px-1.5 rounded" style={{ background: C.ok, color: "#fff" }}>neu</span>}
                  </div>
                  <div className="text-xs" style={{ color: C.muted }}>
                    {l.ort} · {l.quelle} · eingespielt {datum(l.angelegt)}
                    {inhaber && inhaber.id !== user.id ? " · " + inhaber.name : ""}
                  </div>
                </div>
                <div className="text-sm text-right w-28" style={{ fontVariantNumeric: "tabular-nums" }}>
                  {num((parseFloat(l.verbrauchStrom) || 0) + (parseFloat(l.verbrauchGas) || 0))} kWh
                </div>
                <span className="inline-flex items-center gap-1.5 text-xs w-36" style={{ color: sp.color }}>
                  <span className="w-2 h-2 rounded-full" style={{ background: sp.color }} />{sp.label}
                </span>
                <ChevronRight size={15} style={{ color: C.muted }} />
              </button>
            );
          })}
        </div>
      ) : (
        <div className="overflow-x-auto pb-2">
          <div className="flex gap-3" style={{ minWidth: LEAD_SPALTEN.length * 244 }}>
            {LEAD_SPALTEN.map((sp) => {
              const drin = sichtbar.filter((l) => leadSpalte(l) === sp.id);
              const menge = drin.reduce((t, l) =>
                t + (parseFloat(l.verbrauchStrom) || 0) + (parseFloat(l.verbrauchGas) || 0), 0);
              return (
                <div key={sp.id} className="flex-1 rounded p-2"
                  style={{
                    minWidth: 232,
                    background: ueber === sp.id ? "#E8EDF3" : "#F6F8FA",
                    border: "1px solid " + (ueber === sp.id ? sp.color : C.line),
                  }}
                  onDragOver={(e) => { e.preventDefault(); setUeber(sp.id); }}
                  onDragLeave={() => setUeber((x) => (x === sp.id ? null : x))}
                  onDrop={(e) => {
                    e.preventDefault();
                    if (zieht) setz(zieht, { status: sp.id });
                    setZieht(null); setUeber(null);
                  }}>
                  <div className="px-2 py-2 mb-1">
                    <div className="flex items-center gap-2">
                      <span className="w-2 h-2 rounded-full" style={{ background: sp.color }} />
                      <span className="text-sm flex-1">{sp.label}</span>
                      <span className="text-xs" style={{ color: C.muted, fontVariantNumeric: "tabular-nums" }}>
                        {drin.length}
                      </span>
                    </div>
                    <div className="text-xs mt-1 ml-4" style={{ color: C.muted, fontVariantNumeric: "tabular-nums" }}>
                      {menge > 0 ? num(menge) + " kWh" : "–"}
                    </div>
                  </div>

                  {drin.map((l) => <Karte key={l.id} l={l} />)}

                  {drin.length === 0 && (
                    <div className="rounded px-2 py-6 text-center text-xs"
                         style={{ border: "1px dashed " + C.line, color: C.muted }}>
                      hierher ziehen
                    </div>
                  )}
                </div>
              );
            })}
          </div>
        </div>
      )}
    </div>
  );
}

/* Auswertung: Termine, Abschlüsse, Quote und Dauer je Vertriebsmitarbeiter */
function LeadAuswertung({ leads, mitarbeiter, user, darfAlles }) {
  const kennzahlen = (menge) => {
    const termine = menge.filter((l) => l.terminDatum && l.terminDatum <= heute()).length;
    const auftrag = menge.filter((l) => leadSpalte(l) === "auftrag");
    const verloren = menge.filter((l) => leadSpalte(l) === "verloren").length;
    const dauern = auftrag.map((l) => tageZwischen(l.angelegt, l.abschlussAm)).filter((x) => x != null);
    return {
      leads: menge.length,
      termine,
      abschluesse: auftrag.length,
      verloren,
      quote: termine > 0 ? (auftrag.length / termine) * 100 : 0,
      dauer: dauern.length ? dauern.reduce((a, b) => a + b, 0) / dauern.length : null,
      menge: menge.reduce((t, l) =>
        t + (parseFloat(l.verbrauchStrom) || 0) + (parseFloat(l.verbrauchGas) || 0), 0),
    };
  };

  const personen = darfAlles
    ? mitarbeiter.filter((m) => ["Vertriebspartner", "Teamleiter", "Leitung Vertrieb"].includes(m.rolle))
    : user.rolle === "Teamleiter"
      ? [user, ...strukturUnter(user.id, mitarbeiter)]
      : [user];

  const zeilen = personen
    .map((m) => ({ m, k: kennzahlen(leads.filter((l) => l.zugewiesen === m.id)) }))
    .filter((z) => z.k.leads > 0)
    .sort((a, b) => b.k.abschluesse - a.k.abschluesse || b.k.quote - a.k.quote);

  const gesamt = kennzahlen(leads);

  const Kachel = ({ k, v, farbe }) => (
    <div className="rounded p-4" style={{ background: C.card, border: "1px solid " + C.line }}>
      <div className="text-xs mb-2" style={{ color: C.muted }}>{k}</div>
      <div className="text-2xl" style={{ color: farbe || C.text, fontVariantNumeric: "tabular-nums" }}>{v}</div>
    </div>
  );

  const Kopf = ({ children, rechts }) => (
    <th className={"px-3 py-2 text-xs font-normal " + (rechts ? "text-right" : "text-left")}
        style={{ color: C.muted, whiteSpace: "nowrap" }}>{children}</th>
  );
  const Zelle = ({ children, rechts, dick }) => (
    <td className={"px-3 py-2.5 text-sm " + (rechts ? "text-right" : "")}
        style={{ fontVariantNumeric: "tabular-nums", whiteSpace: "nowrap",
                 borderTop: "1px solid " + C.line, fontWeight: dick ? 500 : 400 }}>{children}</td>
  );

  return (
    <div className="space-y-5">
      <div className="grid grid-cols-2 lg:grid-cols-4 gap-3">
        <Kachel k="Termine wahrgenommen" v={gesamt.termine} />
        <Kachel k="Abschlüsse" v={gesamt.abschluesse} farbe={C.ok} />
        <Kachel k="Verloren" v={gesamt.verloren} farbe={gesamt.verloren ? C.warn : C.text} />
        <Kachel k="Abschlussquote auf Termin" v={num(gesamt.quote, 0) + " %"} />
      </div>

      <div className="grid sm:grid-cols-2 gap-3">
        <Kachel k="Ø Tage von Eingang bis Abschluss"
          v={gesamt.dauer != null ? num(gesamt.dauer, 0) : "–"} />
        <Kachel k="Menge in den Leads (kWh/Jahr)" v={num(gesamt.menge)} />
      </div>

      {zeilen.length > 0 && (
        <div className="rounded overflow-x-auto" style={{ background: C.card, border: "1px solid " + C.line }}>
          <table className="w-full" style={{ minWidth: 720 }}>
            <thead>
              <tr>
                <Kopf>Vertriebsmitarbeiter</Kopf>
                <Kopf rechts>Leads</Kopf>
                <Kopf rechts>Termine</Kopf>
                <Kopf rechts>Abschlüsse</Kopf>
                <Kopf rechts>Verloren</Kopf>
                <Kopf rechts>Quote</Kopf>
                <Kopf rechts>Ø Tage</Kopf>
              </tr>
            </thead>
            <tbody>
              {zeilen.map(({ m, k }) => (
                <tr key={m.id}>
                  <Zelle>
                    <span className="inline-flex items-center gap-2">
                      <Avatar m={m} size={26} />
                      <span>{m.name}
                        <span className="block text-xs" style={{ color: C.muted }}>
                          {m.rolle} · Team {m.team}
                        </span>
                      </span>
                    </span>
                  </Zelle>
                  <Zelle rechts>{k.leads}</Zelle>
                  <Zelle rechts>{k.termine}</Zelle>
                  <Zelle rechts>{k.abschluesse}</Zelle>
                  <Zelle rechts>{k.verloren}</Zelle>
                  <Zelle rechts dick>{num(k.quote, 0)} %</Zelle>
                  <Zelle rechts>{k.dauer != null ? num(k.dauer, 0) : "–"}</Zelle>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}

      <p className="text-xs" style={{ color: C.muted, maxWidth: "68ch" }}>
        Als Termin zählt ein Lead mit Termindatum, das nicht in der Zukunft liegt. Die Quote setzt
        Abschlüsse ins Verhältnis zu wahrgenommenen Terminen. Die Dauer misst die Tage vom Einspielen
        des Leads bis zum Verschieben in die Spalte Auftrag.
      </p>
    </div>
  );
}

/* Versorger, mit denen zusammengearbeitet wird */
function Versorgerliste({ versorger, setVersorger, user, standard, setStandard }) {
  const [name, setName] = useState("");
  const [notiz, setNotiz] = useState("");
  const [branchen, setBranchen] = useState("");
  const darfAendern = user.rolle === "Geschäftsführung";

  const anlegen = () => {
    const sauber = name.trim();
    if (!sauber) return;
    if (versorger.some((v) => v.name.toLowerCase() === sauber.toLowerCase())) return;
    setVersorger([...versorger, { id: "v-" + uid(), name: sauber, notiz: notiz.trim(), branchen: branchen.trim() }]);
    setName(""); setNotiz(""); setBranchen("");
  };

  return (
    <div>
      <p className="text-sm mb-5" style={{ color: C.muted, maxWidth: "60ch" }}>
        Diese Liste erscheint beim Kalkulationsteam im Auswahlfeld, wenn ein Auftrag bestätigt wird.
        {darfAendern ? "" : " Ändern darf sie nur die Geschäftsführung."}
      </p>
      <div className="mb-5"><UmlagenPflege user={user} /></div>

      {darfAendern && (
        <div className="rounded p-4 mb-5" style={{ background: C.card, border: "1px solid " + C.strom }}>
          <div className="text-sm mb-1">Anteil an der Gesamtprovision</div>
          <p className="text-xs mb-3" style={{ color: C.muted, maxWidth: "64ch" }}>
            Welcher Anteil der ausgewiesenen Gesamtprovision tatsächlich bei EGC ankommt. Der Wert
            gilt für alle Versorger, sofern beim einzelnen Versorger unten nichts anderes eingetragen ist.
            Die Sätze der Vertriebspartner rechnen weiterhin auf die volle Gesamtprovision.
            Nur die Geschäftsführung sieht diese Werte.
          </p>
          <div className="sm:max-w-xs">
            <Feld label="Vorgabe in Prozent" value={standard}
              onChange={(v) => setStandard(v.replace(/[^\d]/g, ""))} />
          </div>
        </div>
      )}

      {darfAendern && (
        <div className="rounded p-4 mb-5" style={{ background: C.card, border: "1px solid " + C.line }}>
          <div className="grid sm:grid-cols-2 gap-4">
            <Feld label="Versorger" value={name} onChange={setName} placeholder="Name des Versorgers" />
            <Feld label="Notiz" value={notiz} onChange={setNotiz}
              placeholder="Konditionen, Ansprechpartner, Besonderheiten" />
            <Feld label="Branchen und Ausschlüsse" value={branchen} onChange={setBranchen}
              placeholder="welche Branchen werden angenommen, welche nicht" breit />
          </div>
          <div className="mt-4">
            <Btn icon={Plus} onClick={anlegen} disabled={!name.trim()}>Versorger anlegen</Btn>
          </div>
        </div>
      )}

      <div className="rounded overflow-hidden" style={{ background: C.card, border: "1px solid " + C.line }}>
        <div className="px-4 py-3 text-sm" style={{ borderBottom: "1px solid " + C.line }}>
          {versorger.length} Versorger
        </div>
        {versorger.length === 0 && (
          <div className="px-4 py-4 text-sm" style={{ color: C.muted }}>Noch kein Versorger angelegt.</div>
        )}
        {versorger.map((v, i) => (
          <div key={v.id} className="flex items-center gap-4 px-4 py-3"
               style={{ borderTop: i ? "1px solid " + C.line : "none" }}>
            <div className="flex-1 min-w-0">
              <div className="text-sm">{v.name}</div>
              {v.notiz && <div className="text-xs" style={{ color: C.muted }}>{v.notiz}</div>}
              {v.branchen && (
                <div className="text-xs mt-0.5" style={{ color: C.gas }}>Branchen: {v.branchen}</div>
              )}
            </div>
            {darfAendern && (
              <input value={v.anteil ?? ""} inputMode="numeric" placeholder={(standard || "–") + " %"}
                title="Eigener Anteil an der Gesamtprovision für diesen Versorger, leer = Vorgabe"
                onChange={(e) => {
                  const w = e.target.value.replace(/[^\d]/g, "");
                  setVersorger(versorger.map((x) => (x.id === v.id ? { ...x, anteil: w } : x)));
                }}
                className="w-16 px-2 py-1 text-sm rounded text-right outline-none"
                style={{ border: "1px solid " + C.line }} />
            )}
            {darfAendern && (
              <button onClick={() => setVersorger(versorger.filter((x) => x.id !== v.id))}
                style={{ color: C.muted }} title="Entfernen">
                <Trash2 size={15} />
              </button>
            )}
          </div>
        ))}
      </div>

      {darfAendern && (
        <p className="text-xs mt-4" style={{ color: C.muted, maxWidth: "60ch" }}>
          Ein entfernter Versorger verschwindet nur aus der Auswahl. Bereits bestätigte Aufträge
          behalten ihren Eintrag, damit die Historie stimmt.
        </p>
      )}
    </div>
  );
}

/* E-Mail-Signatur für den Vertrieb: Daten wie auf der Visitenkarte. Das Logo laden die Mailprogramme
   über die volle Adresse, deshalb fest auf das veröffentlichte Portal. */
const PORTAL_ADRESSE = "https://egc-vertriebsportal.netlify.app";
const htmlSicher = (t) => String(t || "").replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;");
function signaturHtml(m) {
  const p = visitenkartenDaten(m), F = FIRMENDATEN;
  const web = (F.website || "www.egc-energie.de").replace(/^https?:\/\//, "");
  const tel = (t) => "tel:" + String(t).replace(/[^\d+]/g, "");
  const a = (href, t) => '<a href="' + href + '" style="color:#16212C;text-decoration:none">' + htmlSicher(t) + "</a>";
  const zeile = (k, v) => '<tr><td style="padding:0 8px 2px 0;color:#6B7787;font-size:11px">' + k + '</td><td style="padding:0 0 2px 0;font-size:12px;white-space:nowrap">' + v + "</td></tr>";
  const kontakt = [
    p.mobil ? zeile("Mobil", a(tel(p.mobil), p.mobil)) : "",
    p.telefon ? zeile("Telefon", a(tel(p.telefon), p.telefon)) : "",
    p.email ? zeile("E-Mail", a("mailto:" + p.email, p.email)) : "",
    zeile("Web", a("https://" + web, web)),
  ].join("");
  const fuss = ["EGC Energie" + (F.vertreter ? " · vertreten durch " + F.vertreter : ""), [F.strasse, F.ort].filter(Boolean).join(", "),
    F.ustId ? "USt-IdNr. " + F.ustId : ""].filter(Boolean).map(htmlSicher).join(" · ");
  return '<table cellpadding="0" cellspacing="0" border="0" style="font-family:Arial,Helvetica,sans-serif;color:#16212C;font-size:12px;line-height:1.4;border-collapse:collapse">'
    + '<tr><td style="padding:0 0 8px 0">'
    + '<div style="font-size:15px;font-weight:bold;color:#0A1626">' + htmlSicher(p.name) + "</div>"
    + (p.titel ? '<div style="font-size:12px;font-weight:bold;color:#4A8C26">' + htmlSicher(p.titel) + "</div>" : "")
    + (p.zusatz ? '<div style="font-size:11px;color:#6B7787">' + htmlSicher(p.zusatz) + "</div>" : "")
    + "</td></tr>"
    + '<tr><td style="border-top:2px solid #6CB43B;padding:10px 0 0 0">'
    + '<table cellpadding="0" cellspacing="0" border="0" style="border-collapse:collapse"><tr>'
    + '<td style="padding:0 14px 0 0;vertical-align:middle"><a href="https://' + web + '"><img src="' + PORTAL_ADRESSE + '/assets/signatur-logo.png" width="110" height="51" alt="EGC Energie" style="display:block;border:0;width:110px;height:51px"></a></td>'
    + '<td style="border-left:1px solid #D8DDE4;padding:0 0 0 14px;vertical-align:middle"><table cellpadding="0" cellspacing="0" border="0" style="border-collapse:collapse">' + kontakt + "</table></td>"
    + "</tr></table></td></tr>"
    + '<tr><td style="padding:10px 0 0 0;font-size:10px;color:#6B7787">' + fuss + "</td></tr></table>";
}
function signaturText(m) {
  const p = visitenkartenDaten(m), F = FIRMENDATEN;
  return [p.name, p.titel, p.zusatz, "", "EGC Energie", p.mobil && "Mobil " + p.mobil, p.telefon && "Telefon " + p.telefon,
    p.email && "E-Mail " + p.email, F.website || "www.egc-energie.de", [F.strasse, F.ort].filter(Boolean).join(", ")]
    .filter((z) => z !== null && z !== undefined && z !== false).join("\n").replace(/\n{3,}/g, "\n\n");
}
async function htmlKopieren(html, text) {
  try {
    if (navigator.clipboard && window.ClipboardItem) {
      await navigator.clipboard.write([new ClipboardItem({
        "text/html": new Blob([html], { type: "text/html" }), "text/plain": new Blob([text], { type: "text/plain" }) })]);
      return true;
    }
  } catch (e) { /* weiter mit dem Ersatzweg */ }
  const div = document.createElement("div");
  div.contentEditable = "true"; div.innerHTML = html;
  Object.assign(div.style, { position: "fixed", left: "-9999px", top: "0" });
  document.body.appendChild(div);
  const bereich = document.createRange(); bereich.selectNodeContents(div);
  const auswahl = window.getSelection(); auswahl.removeAllRanges(); auswahl.addRange(bereich);
  let ok = false; try { ok = document.execCommand("copy"); } catch (e) { ok = false; }
  auswahl.removeAllRanges(); div.remove();
  return ok;
}
function EmailSignatur({ m }) {
  const [hinweis, setHinweis] = useState("");
  const [anleitung, setAnleitung] = useState(false);
  const html = signaturHtml(m);
  const p = visitenkartenDaten(m);
  const datei = () => {
    const voll = '<!doctype html><html><head><meta charset="utf-8"><title>Signatur ' + htmlSicher(p.name) + "</title></head><body>" + html + "</body></html>";
    dateiLaden({ name: "Signatur_EGC_" + p.name.replace(/[^\wäöüÄÖÜß]+/g, "_") + ".htm", typ: "text/html",
      url: "data:text/html;base64," + btoa(unescape(encodeURIComponent(voll))) });
  };
  return (
    <div className="rounded p-4 mb-4" style={{ background: C.card, border: "1px solid " + C.line }}>
      <div className="text-sm">Deine E-Mail-Signatur</div>
      <div className="text-xs mb-3" style={{ color: C.muted }}>
        Mit deinen Daten wie auf der Visitenkarte. Einmal kopieren und in deinem Mailprogramm als Signatur einfügen.
      </div>
      <div className="rounded p-4 mb-3 overflow-x-auto" style={{ background: "#fff", border: "1px solid " + C.line }}
           dangerouslySetInnerHTML={{ __html: html.split(PORTAL_ADRESSE + "/assets/").join("/assets/") }} />
      <div className="flex flex-wrap gap-2">
        <Btn icon={Check} onClick={async () => {
          const ok = await htmlKopieren(html, signaturText(m));
          setHinweis(ok ? "Kopiert. Jetzt im Mailprogramm in das Signaturfeld einfügen." : "Kopieren hat nicht geklappt. Bitte die Datei herunterladen.");
        }}>Signatur kopieren</Btn>
        <Btn variante="hell" icon={FileText} onClick={datei}>Als Datei (.htm)</Btn>
        <Btn variante="hell" onClick={() => setAnleitung(!anleitung)}>{anleitung ? "Anleitung ausblenden" : "So richtest du sie ein"}</Btn>
      </div>
      {hinweis && <p className="text-xs mt-2" style={{ color: C.ok }}>{hinweis}</p>}
      {anleitung && (
        <div className="text-xs mt-3 space-y-2" style={{ color: C.text, maxWidth: "70ch" }}>
          <p><b>Outlook am PC:</b> Datei › Optionen › E-Mail › Signaturen › Neu. Namen vergeben, in das große Feld klicken und einfügen (Strg + V), Speichern.
             Im neuen Outlook: Zahnrad › Konten › Signaturen.</p>
          <p><b>Strato Webmail:</b> Einstellungen (Zahnrad) › E-Mail › Signaturen › neue Signatur anlegen und einfügen.</p>
          <p><b>iPhone (Mail-App):</b> Einstellungen › Apps › Mail › Signatur, lange in das Feld tippen › Einfügen.
             Die Outlook-App am Handy übernimmt nur Text ohne Logo.</p>
          <p style={{ color: C.muted }}>Am einfachsten geht es am PC: Portal dort öffnen, „Signatur kopieren“ und in Outlook einfügen.
             Stimmen Telefonnummer oder Berufsbezeichnung nicht, sag der Geschäftsführung Bescheid, sie pflegt die Daten unter Visitenkarten.</p>
        </div>
      )}
    </div>
  );
}

